# Stories for albums 801–850 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220–230 words per story (min ~210), three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_801_850.py; later edits: python3 tools/apply_stories.py stories_801_850
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(802, [
'''פאלפ היא להקה משפילד שבצפון אנגליה, שג׳רוויס קוקר הקים כשהיה עוד נער בבית הספר, בסוף שנות השבעים. במשך יותר מעשר שנים היא כמעט לא הצליחה: הופעות קטנות, תקליטים שאיש לא קנה, הרכב שהתחלף שוב ושוב. רק באמצע שנות התשעים, כשגל הבריטפופ הציף את אנגליה, הגיעה סוף סוף ההצלחה. Different Class יצא בסתיו 1995, הגיע למקום הראשון במצעד הבריטי וזכה בפרס מרקורי, וקוקר, גבוה, רזה, במשקפיים ובחליפה מיושנת, הפך לאחד האנשים המדוברים במדינה.''',
'''השירים הם סיפורים קטנים וחדים על החיים הבריטיים: על מעמדות, על מין, על מסיבות ועל השכונה. Common People מספר על סטודנטית עשירה שרוצה "לחיות כמו האנשים הפשוטים", וקוקר עונה לה בזעם הולך וגובר שהיא לעולם לא תבין מה זה באמת. Disco 2000 הוא שיר פופ קופצני על חברת ילדות בשם דבורה, ועל פגישה שקבעו פעם ליד המזרקה בשנת אלפיים. Something Changed הוא שיר אהבה עדין על המקריות שבה אנשים נפגשים. הקול של קוקר עובר מלחישה מפתה לצעקה, והמילים שלו מצחיקות, עצובות ומדויקות.''',
'''Different Class נחשב לאחד מאלבומי הבריטפופ הטובים ביותר, לצד Parklife של בלר (אלבום 772) ו־Definitely Maybe של אואזיס (אלבום 768). מה שמייחד אותו הוא נקודת המבט: לא הכוכב המנצח, אלא הבחור הצנום מהצד, שמסתכל על כולם ורואה הכל. Common People הפך להמנון של דור שלם, וקוקר נשאר דמות אהובה באנגליה.''',
'''הקשיבו ל־Common People עד הסוף, ושימו לב איך השיר מאיץ ומתגבר בהדרגה, עד שהוא כמעט מתפוצץ. אחר כך שמעו את Bar Italia, השיר האחרון, על בוקר עייף אחרי לילה ארוך בלונדון.''',
], [
('Common People', 'סיפור חד ומצחיק על סטודנטית עשירה, שהולך ומתגבר עד פיצוץ אדיר.'),
('Disco 2000', 'פופ קופצני על חברת ילדות ופגישה שנקבעה פעם ליד המזרקה.'),
('Something Changed', 'שיר אהבה עדין ומתוק על המקריות שבה שני אנשים נפגשים.'),
])

add(803, [
'''לפטפילד הם שני מוזיקאים מלונדון, ניל ברנס ופול דיילי, שהתחילו לעבוד יחד בסוף שנות השמונים, בימים שבהם מוזיקת הדאנס האלקטרונית כבשה את בריטניה. הם הוציאו כמה סינגלים שהפכו לאהובים במועדונים, וב־1995 הגיע אלבום הבכורה שלהם, Leftism. הוא היה מועמד לפרס מרקורי, נמכר היטב, ונחשב עד היום לאחד האלבומים שהראו שמוזיקה אלקטרונית יכולה להיות אלבום שלם להאזנה בבית, ולא רק ערב בריקודים.''',
'''הצליל מחבר בין האוס, טכנו ודאב, הסגנון הג׳מייקני שבו הבס עמוק והצלילים מהדהדים. יש כאן קצבים ארוכים ומתפתחים, בס שמרגישים בגוף, וזמרים אורחים מעולמות שונים. Release the Pressure פותח עם הזמר הג׳מייקני ארל סיקסטין, ומשלב רגאיי עם קצב אלקטרוני. Open Up הוא שיתוף פעולה מפתיע עם ג׳ון ליידון, הזמר של הסקס פיסטולס, שצועק מעל קצב מהיר וסוחף. Original, עם הזמרת טוני הלידיי, איטי וחלומי יותר, ו־Song of Life הוא מסע ארוך ויפה שנבנה לאט.''',
'''Leftism הפך לאחד מאבני היסוד של מה שנקרא אז "דאנס לאלבומים", לצד אורביטל (אלבומים 751 ו־781) והכימיקל בראדרס (אלבום 793). לפטפילד היו ידועים גם בהופעות רועשות במיוחד, עם מערכת הגברה עוצמתית מאוד. כמה מהקטעים שלהם הופיעו בסרטים ובפרסומות, והאלבום נשמע רענן גם היום. ברנס ודיילי עבדו עליו לאט ובקפידה, במשך כמה שנים, וזה מורגש: כל קטע בנוי בסבלנות, שכבה אחרי שכבה, וכמעט שום דבר בו לא נשמע מקרי או חפוז.''',
'''זה אלבום שכדאי לשמוע בווליום גבוה, ברמקולים טובים או באוזניות, כדי להרגיש את הבס. התחילו ב־Release the Pressure, ותנו לו לבנות את עצמו לאט.''',
], [
('Release the Pressure', 'פתיחה שמחברת רגאיי וקצב אלקטרוני, עם קול חם ובס עמוק.'),
('Open Up', 'ג׳ון ליידון צועק מעל קצב מהיר וסוחף, שיתוף פעולה מפתיע וחשמלי.'),
('Song of Life', 'מסע אלקטרוני ארוך ויפה, שנבנה לאט ומתרומם בהדרגה.'),
])

add(804, [
'''דיאנג׳לו, מייקל ארצ׳ר, גדל בריצ׳מונד שבווירג׳יניה, בנו של כומר, ולמד לנגן על פסנתר ועל עוגב בכנסייה כבר כילד קטן. כנער הוא זכה בתחרות הכישרונות המפורסמת של תיאטרון אפולו בהארלם, ובגיל עשרים ואחת יצא אלבום הבכורה שלו, Brown Sugar, ב־1995. בזמן שמוזיקת הנשמה של אותן שנים הייתה מלאה בקצבים חדים ובהפקות נוצצות, דיאנג׳לו הלך לכיוון אחר לגמרי: חם, איטי ומלא נשמה ישנה.''',
'''דיאנג׳לו ניגן בעצמו על רוב הכלים, ובעיקר על פסנתר חשמלי ועל עוגב, שנותנים לאלבום צליל עגול ורך. הקצבים מושפעים מהיפ הופ, אבל השירה והמלודיות שואבות מהסול של שנות השבעים, ממרווין גיי, מאל גרין ומפרינס. השיר שנותן לאלבום את שמו, Brown Sugar, הוא גרוב איטי וממכר, עם קול שמתפתל ומתלחש. Lady הוא שיר אהבה מתוק עם פזמון שנדבק מיד, ו־Cruisin׳ הוא גרסה מלטפת לשיר הידוע של סמוקי רובינסון. האלבום כולו נשמע כמו לילה ארוך ושקט.''',
'''Brown Sugar נחשב לאחד האלבומים שפתחו את מה שנקרא "ניאו סול", גל של זמרים צעירים שחזרו לצליל החם והאורגני של הסול הקלאסי. מקסוול (אלבום 824) ואריקה באדו הגיעו מיד אחריו. דיאנג׳לו עצמו הוציא מעט מאוד אלבומים, עם הפסקות ארוכות של שנים ביניהם, אבל כל אחד מהם נחשב לאירוע. גם היום, זמרים צעירים רבים מזכירים את Brown Sugar כאלבום שלימד אותם איך סול יכול להישמע חם, אישי ומודרני בבת אחת.''',
'''השוו בין Brown Sugar לבין What's Going On של מרווין גיי (אלבום 208), ושמעו כמה דיאנג׳לו למד ממנו, בקול הכפול ובקצב הרגוע.''',
], [
('Brown Sugar', 'גרוב איטי וממכר, עם עוגב חם וקול שמתפתל ומתלחש.'),
('Lady', 'שיר אהבה מתוק עם פזמון שנדבק כבר בהאזנה הראשונה.'),
("Cruisin'", 'גרסה מלטפת ורכה לשיר הידוע של סמוקי רובינסון, עם כלי מיתר.'),
])

add(805, [
'''כשאואזיס ממנצ׳סטר הוציאו את (What's the Story) Morning Glory? באוקטובר 1995, הם כבר היו להקה מצליחה, אחרי Definitely Maybe (אלבום 768). אבל האלבום השני הפך אותם לתופעה. כמה חודשים לפני כן התנהל "הקרב" המפורסם מול בלר, כשהשתי הלהקות הוציאו סינגל באותו יום, והעיתונים הפכו את זה לסיפור לאומי. בלר ניצחו בקרב על הסינגל, אבל אואזיס ניצחו במלחמה: האלבום נמכר במיליוני עותקים והפך לאחד הנמכרים בתולדות בריטניה.''',
'''את השירים כתב נואל גלאגר, האח המבוגר, והזמר הוא ליאם, האח הצעיר, עם קול מחוספס ויהיר. הצליל גדול ורחב: גיטרות עבות, מלודיות פשוטות שמזמינות לשיר יחד, והשפעה גלויה מהביטלס. Wonderwall, עם הגיטרה האקוסטית והצ׳לו, הפך לאחד השירים המוכרים בעולם. Don't Look Back in Anger, שבו שר נואל עצמו, הוא בלדה עם פסנתר שנפתחת לפזמון אדיר. Champagne Supernova, השיר האחרון, נמשך יותר משבע דקות, עם פול ולר כאורח בגיטרה.''',
'''באוגוסט 1996 הופיעו אואזיס פעמיים בנבוורת׳, מול כמאתיים וחמישים אלף איש בשני ערבים, אחת ההופעות הגדולות בתולדות בריטניה. זה היה שיא הבריטפופ. מאז, הלהקה התפרקה וחזרה, אבל השירים מהאלבום הזה נשארו מושרים בכל פאב ובכל מגרש כדורגל. המבקרים לא תמיד אהבו את האלבום כשיצא, וחלקם מצאו אותו פשוט מדי, אבל הקהל החליט אחרת, ועם השנים גם רבים מהמבקרים שינו את דעתם.''',
'''השוו את האלבום ל־Different Class של פאלפ (אלבום 802), שיצא באותו חודש: שני צדדים שונים מאוד של אותה תקופה. ושימו לב לפזמון של Don't Look Back in Anger.''',
], [
('Wonderwall', 'גיטרה אקוסטית וצ׳לו, ואחד השירים המוכרים בעולם מאז שנות התשעים.'),
("Don't Look Back in Anger", 'נואל שר בלדה עם פסנתר, שנפתחת לפזמון שכל קהל שר יחד.'),
('Champagne Supernova', 'סיום ארוך וחולמני של שבע דקות, עם פול ולר בגיטרה.'),
])

add(806, [
'''גולדי, קליפורד פרייס, גדל בוולברהמפטון שבאנגליה, ובשנות השמונים התפרסם בכלל כאמן גרפיטי, עם שיני זהב שהפכו לסימן ההיכר שלו. בתחילת שנות התשעים הוא התאהב בג׳אנגל, המוזיקה האלקטרונית המהירה שצמחה במועדונים של לונדון, עם קצבי תופים שבורים ומהירים ובס עמוק ואיטי. הוא הקים חברת תקליטים בשם מטלהדז, וב־1995 הוציא את Timeless, אחד האלבומים הראשונים של הסגנון, שנקרא אחר כך דראם אנד בייס, שהגיע לקהל רחב.''',
'''הקטע שפותח את האלבום ונותן לו את שמו, Timeless, נמשך יותר מעשרים דקות, ובנוי כמו יצירה בכמה חלקים. בתוכו מסתתר Inner City Life, שיר יפה במיוחד עם קולה של הזמרת דיאן שרלמן, שמרחף מעל תופים מהירים ומתוחים. גולדי שילב כלי מיתר, פסנתר ג׳אז ואווירה של סול, כך שהמוזיקה נשמעת גם מהירה וגם רכה, גם עירונית וגם חולמנית. Angel ו־State of Mind ממשיכים באותה רוח, עם שירה ומלודיות שמרככות את הקצב.''',
'''Timeless הראה שג׳אנגל הוא לא רק מוזיקה למועדונים, אלא משהו שאפשר להקשיב לו בבית כמו לאלבום ג׳אז או סול. הוא נכנס לעשירייה הראשונה במצעד הבריטי, וגולדי הפך לכוכב, ואחר כך גם לשחקן ולדמות טלוויזיה מוכרת באנגליה. דרכו, הרבה אנשים שמעולם לא נכנסו למועדון ג׳אנגל גילו את הסגנון, ואמנים רבים, מפופ ועד ג׳אז, התחילו לשאול ממנו קצבים ורעיונות. גולדי גם הוכיח שתקליטן ואמן גרפיטי בלי השכלה מוזיקלית יכול לבנות יצירה גדולה ושאפתנית, כמעט סימפונית.''',
'''הקשיבו לקטע הפתיחה הארוך מתחילתו ועד סופו, באוזניות, ושימו לב איך מעל התופים המהירים נשאר כל הזמן משהו איטי ונינוח, הבס והקול.''',
], [
('Timeless', 'יצירה של עשרים דקות, עם תופים מהירים, כלי מיתר וקול נשי מרחף.'),
('State of Mind', 'קטע רך ומלודי, שמראה כמה ג׳אנגל יכול להיות עדין.'),
('Angel', 'שירה חמה מעל קצב שבור ומהיר, אווירה של לילה בעיר.'),
])

add(807, [
'''אלאניס מוריסט נולדה באוטווה שבקנדה, ועוד כנערה הייתה כוכבת פופ קטנה בארצה, עם שני אלבומים של פופ ריקודים קליל. בגיל עשרים בערך היא עברה ללוס אנג׳לס, התחילה לכתוב עם המפיק גלן באלארד, ובתוך זמן קצר נולדו שירים אישיים, כועסים וכנים בהרבה. Jagged Little Pill יצא ב־1995 בחברת התקליטים של מדונה, ולאט לאט הפך לאחת התופעות הגדולות של העשור. הוא נמכר בעשרות מיליוני עותקים בכל העולם, וזכה בפרס הגראמי לאלבום השנה.''',
'''הצליל הוא רוק אלטרנטיבי נגיש, עם גיטרות, תופים חזקים ומלודיות שנכנסות מיד לראש, אבל מה שבולט הוא הקול של מוריסט: היא שרה, צועקת, צוחקת ומתלוננת, כמו מישהי שכותבת ביומן ולא אכפת לה מי ישמע. You Oughta Know, עם פלי מהרד הוט צ׳ילי פפרס בבס, הוא מכתב זועם לאקס שעזב. Hand in My Pocket הוא שיר קליל ואופטימי על הסתירות שבכל אחד מאיתנו. Ironic, עם הפזמון המפורסם, הפך לאחד השירים המוכרים של שנות התשעים, ואנשים מתווכחים עד היום אם הדוגמאות שבו באמת אירוניות.''',
'''Jagged Little Pill פתח את הדלת לגל שלם של זמרות־כותבות שכתבו בגלוי על כעס, על מין ועל בלבול, בלי לייפות דבר. הוא נשמע כמו קול של צעירה אמיתית ולא של כוכבת מעוצבת, ובגלל זה כל כך הרבה בנות ובנים הזדהו איתו. שנים אחר כך נבנה על השירים מהאלבום מחזמר שלם, שעלה גם בברודווי.''',
'''השוו את מוריסט לטורי איימוס (אלבום 727) ולפיונה אפל (אלבום 819): שלוש זמרות שכתבו באותן שנים על אותם נושאים, כל אחת בדרך אחרת לגמרי. ושימו לב לשיר הנסתר בסוף האלבום, אם הוא מופיע.''',
], [
('You Oughta Know', 'מכתב זועם וחשוף לאקס, עם בס סוער וצעקה שלא מתנצלת.'),
('Hand in My Pocket', 'שיר קליל ואופטימי על הסתירות הקטנות שבכל אחד מאיתנו.'),
('Ironic', 'פזמון מפורסם ודוגמאות שאנשים מתווכחים עליהן עד היום.'),
])

add(808, [
'''סקרימינג טריז הגיעו מאלנסבורג, עיירה קטנה במדינת וושינגטון, הרחק מסיאטל. הלהקה התחילה באמצע שנות השמונים, סביב שני אחים, גארי לי ווואן קונר, והזמר מארק לנגן, בעל אחד הקולות העמוקים והמחוספסים ברוק. הם היו חלק מסצנת הגראנג׳ עוד לפני שהיה לה שם, אבל אף פעם לא הצליחו כמו נירוונה או סאונדגרדן. Dust, שיצא ב־1996, היה האלבום האחרון שלהם, ורבים חושבים שהוא גם הטוב ביותר.''',
'''הצליל של Dust רחב וחם יותר מהגראנג׳ הרגיל: יש בו גיטרות כבדות, אבל גם עוגב, גיטרות אקוסטיות, צלילים מזרחיים קלים והשפעה ברורה מהרוק הפסיכדלי של שנות השישים. הקול של לנגן נשמע כמו של אדם שכבר ראה הכל, עייף וחכם, והמילים עוסקות באובדן, בחטא ובגאולה. Halo of Ashes פותח בעוצמה, עם מלודיה מתפתלת. All I Know הוא שיר רוק עם פזמון שנכנס לראש. Dying Days, עם הגיטריסט מייק מקקרדי מפרל ג׳ם, הוא שיר אפל ויפה, ו־Gospel Plow, השיר האחרון, מבוסס על שיר גוספל ישן.''',
'''Dust לא הצליח להפוך את הלהקה לכוכבת, ואחרי כמה שנים היא התפרקה. אבל מארק לנגן המשיך לקריירת סולו ארוכה ומוערכת, שיתף פעולה עם קווינס אוף דה סטון אייג׳ ועם אמנים רבים, והפך לאחד הקולות האהובים של הרוק האלטרנטיבי, עד מותו ב־2022.''',
'''אם אהבתם את Superunknown של סאונדגרדן (אלבום 769) או את Dirt של אליס אין צ׳יינס (אלבום 730), זה הצד החם והאיטי יותר של אותה סצנה. שמעו את הקול של לנגן באוזניות, בשקט.''',
], [
('Halo of Ashes', 'פתיחה עוצמתית עם מלודיה מתפתלת וגוון מזרחי עדין.'),
('All I Know', 'שיר רוק חזק עם פזמון שנכנס לראש וקול עמוק ומחוספס.'),
('Dying Days', 'שיר אפל ויפה, עם סולו גיטרה של מייק מקקרדי מפרל ג׳ם.'),
])

add(809, [
'''סופר פרי אנימלס היא להקה מקארדיף שבוויילס, שהתחילה לשיר בוולשית, השפה המקומית, ורק אחר כך עברה לאנגלית. הזמר, גרף ריס, כותב שירים מוזרים, מצחיקים ומלאי דמיון, והלהקה כולה נשמעה כמו חבורה של חברים שנהנים להשתולל באולפן. היא חתמה בחברת התקליטים קריישן, אותה חברה שבה הקליטו אואזיס ופריימל סקרים, ו־Fuzzy Logic, אלבום הבכורה, יצא ב־1996. על העטיפה יש תמונות של הווארד מרקס, מבריח סמים וולשי מפורסם, בכל התחפושות שבהן השתמש כדי להתחמק מהמשטרה.''',
'''המוזיקה היא פופ פסיכדלי, שמחבר בין גיטרות של בריטפופ, הרמוניות בסגנון הביץ׳ בויז והביטלס, וקצת שגעון אלקטרוני. כל שיר נשמע אחר, וכמעט בכל אחד יש רעיון מפתיע. Something 4 the Weekend הוא שיר פופ שמח וקליל על תוכניות לסוף השבוע. Hometown Unicorn מספר על חד קרן שהלך לאיבוד, עם מלודיה מתוקה ועצובה. If You Don't Want Me to Destroy You הוא שיר שקט ויפה, ו־God! Show Me Magic פותח את האלבום במהירות ובאנרגיה של פאנק.''',
'''הלהקה הייתה ידועה גם בשטויות שלה: היא קנתה טנק צבאי ישן, צבעה אותו בכחול והביאה אותו לפסטיבלים. אבל מאחורי ההומור עמדה להקה רצינית מאוד, שהוציאה סדרה ארוכה של אלבומים מצוינים, כולל אלבום שלם בוולשית, ונחשבה לאחת הלהקות המקוריות של בריטניה בשנות התשעים.''',
'''אם אהבתם את I Should Coco של סופרגראס (אלבום 796), שתי הלהקות חולקות את אותה שמחה צעירה. התחילו ב־Something 4 the Weekend, ואחר כך תנו לשאר האלבום להפתיע.''',
], [
('Something 4 the Weekend', 'פופ שמח וקליל על תוכניות לסוף השבוע, עם פזמון מתוק.'),
('Hometown Unicorn', 'שיר מתוק ועצוב על חד קרן שהלך לאיבוד, עם הרמוניות יפות.'),
('If You Don\'t Want Me to Destroy You', 'שיר שקט ויפה, עם מלודיה עדינה ואווירה חולמנית.'),
])

add(810, [
'''פטבוי סלים הוא נורמן קוק מברייטון, שכבר היה מוזיקאי מצליח עוד לפני השם הזה: בשנות השמונים ניגן בס בלהקת הפופ ההאוסמרטינס, ואחר כך הצליח עם פרויקטים של מוזיקת ריקודים. באמצע שנות התשעים הוא התחיל לתקלט במועדון קטן בברייטון, ותחת השם פטבוי סלים הוציא ב־1996 את Better Living Through Chemistry, אלבום הבכורה שלו, בחברת התקליטים הקטנה סקינט. הוא היה אחד האלבומים הראשונים של סגנון שנקרא "ביג ביט".''',
'''ביג ביט הוא מוזיקה אלקטרונית שמחה ורועשת, שמחברת בין קצבים של היפ הופ, גיטרות של רוק, דגימות מתקליטים ישנים ובס כבד. פטבוי סלים הוא אמן של דגימות: הוא לוקח קטע קצר מתקליט נשכח, חוזר עליו שוב ושוב, ובונה ממנו מסיבה. Everybody Needs a 303 מוקדש למכשיר הבס הקטן של רולנד, שהפך לצליל המרכזי של מוזיקת האסיד. Going Out of My Head משתמש בריף גיטרה ידוע מהשישים, ו־Santa Cruz הוא קטע מסחרר שבונה את עצמו לאט. הכל נשמע כמו ערב שמח במועדון, בלי שום יומרה.''',
'''האלבום הזה היה רק ההתחלה: שנתיים אחר כך הוציא פטבוי סלים את You've Come a Long Way, Baby, עם Praise You ו־Right Here, Right Now, והפך לאחד התקליטנים המפורסמים בעולם. אבל כאן אפשר לשמוע את הנוסחה שלו בפעם הראשונה, צעירה, מבולגנת ומלאת הומור.''',
'''השוו את האלבום ל־Exit Planet Dust של הכימיקל בראדרס (אלבום 793), שעשו אז מוזיקה דומה. שמעו את Everybody Needs a 303, ושימו לב לצליל הבס המפעפע שחוזר שוב ושוב.''',
], [
('Everybody Needs a 303', 'מחווה שמחה לצליל הבס המפעפע של מוזיקת האסיד.'),
('Going Out of My Head', 'ריף גיטרה מהשישים הופך כאן למסיבה רועשת ומטורפת.'),
('Santa Cruz', 'קטע מסחרר שבונה את עצמו לאט, עד שאי אפשר לשבת.'),
])

add(811, [
'''קול קית׳, קית׳ תורנטון, הוא ראפר מהברונקס שבניו יורק, שהתפרסם כבר בשנות השמונים עם הלהקה אולטרמגנטיק MCs. הוא תמיד היה מוזר, מקורי ובלתי צפוי, ובאמצע שנות התשעים המציא דמות חדשה: דוקטור אוקטגון, רופא נשים ומנתח מטורף, חייזר שמטייל בזמן ומגיע מכוכב צדק. Dr. Octagonecologyst יצא ב־1996 בחברה קטנה, הפך לשמועה בין אוהבי היפ הופ, ושנה אחר כך הוצא מחדש בחברה גדולה, והגיע לקהל רחב בהרבה.''',
'''את המוזיקה הפיק דן דה אוטומייטור, מפיק מסן פרנסיסקו, שבנה עולם מוזיקלי מפחיד ויפה: כלי מיתר, פסנתר, צלילים חלליים וקצבים איטיים ומאיימים, כמו פסקול לסרט מדע בדיוני זול. התקליטן קיו־ברט, מגדולי האמנים של הפטיפון, מוסיף שריטות מבריקות. המילים של קול קית׳ הן זרם של מילים רפואיות, דימויים מוזרים, הומור גס ושטויות מבריקות, ולפעמים הן בוטות מאוד. Blue Flowers, עם כינור מרחף ומבשר רעות, הוא הקטע המפורסם. Earth People מצחיק ומוזר, ו־3000 נשמע כמו טיסה בחלל.''',
'''Dr. Octagonecologyst הפך לאחד האלבומים החשובים של ההיפ הופ העצמאי, והראה שאפשר לעשות ראפ ניסיוני, מצחיק ואפל, בלי לחשוב על המצעדים. דן דה אוטומייטור המשיך לעבוד עם גורילז ועם פרויקטים רבים, וקול קית׳ המשיך להמציא דמויות חדשות עוד שנים רבות. האלבום מצחיק ומטריד באותה מידה, וחלק מהקסם שלו הוא שאף פעם לא ברור עד כמה קול קית׳ רציני. הדמות של הרופא החייזר הפכה לאגדה בקרב אוהבי ההיפ הופ, וחזרה גם באלבומים מאוחרים יותר.''',
'''אם תמשיכו ל־Endtroducing של די ג׳יי שאדו (אלבום 816), תשמעו עוד אלבום מאותו עולם: שאדו הקליט אותו בעזרת ציוד שהשאיל לו דן דה אוטומייטור. התחילו ב־Blue Flowers.''',
], [
('Blue Flowers', 'כינור מרחף ומבשר רעות, ראפ מוזר וקצב איטי ומאיים.'),
('Earth People', 'מצחיק ומוזר, ההכרזה של הרופא החייזר לתושבי כדור הארץ.'),
('3000', 'קצב חללי וצלילים מרחפים, כמו טיסה בספינת חלל ישנה.'),
])

add(812, [
'''סטריאולאב היא להקה מלונדון שהקימו בתחילת שנות התשעים הגיטריסט האנגלי טים גיין והזמרת הצרפתייה לטישיה סאדייר. השם שלה לקוח מתקליטי הדגמה ישנים של ציוד סטריאו מהשישים, וזה מתאים: הלהקה אהבה צלילים של פעם, עוגבים ישנים, סינתיסייזרי מוּג ותופים חוזרים ומהפנטים, וחיברה אותם לרעיונות חדשים לגמרי. Emperor Tomato Ketchup, שיצא ב־1996 ונקרא על שם סרט יפני ניסיוני, היה האלבום שבו הם הגיעו לשיא, והפך לאהוב במיוחד על מבקרים ועל סטודנטים בכל העולם.''',
'''המוזיקה מחברת דברים שלא נראים קשורים: הקצב העיקש של הקראוטרוק הגרמני, כמו של נוי! (אלבום 329) וקאן, המלודיות הקלילות של מוזיקת לאונג׳ ובוסה נובה, וג׳אז רך. סאדייר שרה בצרפתית ובאנגלית, בקול רגוע ומתוק, ולצידה שרה מרי הנסן קולות רקע, והשתיים יוצרות הרמוניות יפות במיוחד. המילים, באופן מפתיע, עוסקות לא פעם בפוליטיקה ובפילוסופיה. Metronomic Underground פותח עם גרוב ארוך ומהפנט, שחוזר על עצמו כמו מכונה. Cybele's Reverie הוא שיר פופ צרפתי מתוק, עם כלי מיתר, ו־Percolator קופצני ושובב.''',
'''ג׳ון מקנטייר מלהקת טורטויז (אלבום 813) עזר בהקלטות ובהפקה. הוא הפך לאחד האלבומים החשובים של אמצע שנות התשעים, השפיע על להקות אינדי ועל מוזיקאים אלקטרוניים רבים, והוכיח שאפשר להיות גם ניסיוני וגם נעים מאוד להאזנה, באותו זמן.''',
'''זה אלבום שמתאים לשמוע ברקע של עבודה או נסיעה, ואז פתאום לשים לב לפרט קטן ומרתק. התחילו ב־Cybele's Reverie, ואחר כך חזרו להתחלה ותנו ל־Metronomic Underground לסחוף אתכם.''',
], [
('Metronomic Underground', 'גרוב ארוך ומהפנט שחוזר על עצמו כמו מכונה, עם קולות מרחפים.'),
("Cybele's Reverie", 'פופ צרפתי מתוק עם כלי מיתר, כמו שיר מסרט ישן.'),
('Percolator', 'קטע קופצני ושובב, עם עוגב ותופים עליזים.'),
])

add(813, [
'''טורטויז היא להקה משיקגו, שהתחילה בתחילת שנות התשעים, ונבנתה כולה סביב הקצב, עם כמה מתופפים ובסיסט. אין בה זמר ואין מילים: היא מנגנת מוזיקה כלית שמחברת רוק, ג׳אז, דאב, מוזיקה אלקטרונית ומוזיקה מינימליסטית, עם ויברפון, מרימבה ובס עמוק. מבקר בריטי טבע באותן שנים את המונח "פוסט רוק", וטורטויז הפכה לאחת הדוגמאות המוכרות שלו. Millions Now Living Will Never Die, שיצא ב־1996, היה האלבום השני שלה, ושמו לקוח מסיסמה דתית ישנה מתחילת המאה העשרים.''',
'''האלבום נפתח ב־Djed, יצירה של כעשרים ואחת דקות, שהיא אחד הקטעים המפורסמים בפוסט רוק. היא בנויה כמו מסע: מתחילה בבס נינוח ובצלילים מתופפים, עוברת דרך פעמונים, מרימבה וצלילים אלקטרוניים, ונחתכת פתאום, כאילו מישהו גזר את הסרט, וממשיכה למקום אחר לגמרי. החיתוכים האלה, שנעשו באולפן, הם חלק מהיופי. Glass Museum עדין ומתפתח לאט, עם גיטרה נקייה וויברפון, ו־The Taut and Tame כבד ואפל יותר, עם בס עמוק וקצב מתוח. הכל נשמע מדויק, רגוע וחכם.''',
'''Millions Now Living Will Never Die הפך לאחד האלבומים שהגדירו את הפוסט רוק, והשפיע על להקות רבות שבאו אחריו. המתופף ג׳ון מקנטייר הפך למפיק מבוקש, ועבד בין היתר עם סטריאולאב (אלבום 812). דייוויד פאחו, הגיטריסט של סלינט (אלבום 701), הצטרף ללהקה בזמן ההקלטות. האלבום גם הראה שלהקת רוק יכולה לוותר על זמר, על מילים ועל פזמונים, ועדיין לרגש.''',
'''כדאי לשמוע את Djed בבת אחת, בלי הפסקה, באוזניות טובות, כמו שמקשיבים ליצירה קלאסית. ואם אהבתם את Spiderland של סלינט (אלבום 701), זה הצד הרגוע והאלקטרוני של אותו רעיון.''',
], [
('Djed', 'מסע של עשרים דקות, עם חיתוכים מפתיעים, פעמונים, בס ומרימבה.'),
('Glass Museum', 'עדין ומתפתח לאט, עם גיטרה נקייה וויברפון שמנצנץ.'),
('The Taut and Tame', 'כבד ואפל יותר, עם בס עמוק וקצב מתוח שלא נרגע.'),
])

add(814, [
'''בק הנסן גדל בלוס אנג׳לס, במשפחה של אמנים, ובתחילת שנות התשעים ניגן פולק ובלוז בבתי קפה קטנים. ב־1994 הוא הפך לכוכב בטעות כמעט, כשהשיר Loser, שהוקלט בסלון של חבר, הפך ללהיט ענק. רבים חשבו שהוא יהיה זמר של להיט אחד, אבל Odelay, שיצא ב־1996, הוכיח שהוא אחד האמנים היצירתיים של הדור. האלבום זכה בפרס הגראמי לאלבום האלטרנטיבי הטוב ביותר, היה מועמד לאלבום השנה, והופיע ברשימות של הטובים של השנה כמעט בכל מקום.''',
'''את האלבום הפיקו הדאסט בראדרס, אותם מפיקים שעשו את Paul's Boutique של הביסטי בויז (אלבום 644), והוא בנוי כמו קולאז׳: היפ הופ, פולק, קאנטרי, בלוז, רוק ופאנק, עם דגימות מעשרות תקליטים, ובק שר, מדבר וראפ מעל הכל. Devils Haircut פותח עם ריף גיטרה מלוכלך ותופים כבדים. Where It's At הוא גרוב נינוח עם פסנתר חשמלי ושורה מפורסמת על "שני פטיפונים ומיקרופון". The New Pollution הוא פופ שמח עם סקסופון בסגנון השישים, ו־Jack-Ass הוא שיר רך ועצוב, שמבוסס על דגימה משיר ישן.''',
'''Odelay נחשב לאחד האלבומים החשובים של שנות התשעים, כי הוא הראה כמה רחוק אפשר ללכת עם רעיון הקולאז׳, בלי לאבד את השיר עצמו. בק המשיך לקריירה ארוכה ומגוונת, ועבר בין סגנונות שונים לגמרי, מפולק שקט ועד פאנק מסיבות.''',
'''שמעו את Odelay אחרי Paul's Boutique של הביסטי בויז (אלבום 644), ושימו לב איך אותם מפיקים יצרו עולם שונה לגמרי. ושימו לב לכלב השעיר שקופץ על העטיפה.''',
], [
('Devils Haircut', 'ריף גיטרה מלוכלך, תופים כבדים וקול מתגרה ומלא ביטחון.'),
("Where It's At", 'גרוב נינוח עם פסנתר חשמלי ושורה מפורסמת על פטיפונים ומיקרופון.'),
('The New Pollution', 'פופ שמח וקליל עם סקסופון בסגנון שנות השישים.'),
])

add(815, [
'''בל אנד סבסטיאן היא להקה מגלזגו שבסקוטלנד, שנולדה כמעט במקרה. סטיוארט מרדוק, צעיר ביישן שכתב שירים בשקט במשך שנים, נרשם לקורס בעסקי מוזיקה במכללה מקומית, והקורס כלל הקלטה והוצאה של תקליט. הוא אסף חברים, הקליט איתם תוך כמה ימים, ו־Tigermilk יצא ב־1996 באלף עותקים בלבד, על תקליט ויניל. העותקים נעלמו מיד, השמועה התפשטה, והאלבום הפך לאחד הפריטים הנדירים והמבוקשים באינדי הבריטי, עד שהוצא מחדש כמה שנים אחר כך.''',
'''המוזיקה רכה, עדינה ומלאה בזיכרונות מפופ של שנות השישים, עם גיטרות אקוסטיות, חצוצרה, צ׳לו, פסנתר וקולות שקטים. מרדוק שר כמו מישהו שמספר סוד, והשירים שלו הם סיפורים קטנים על נערים ונערות בודדים, על בית ספר, על דת ועל אהבה מבולבלת, עם הומור עדין ועצב שקט. The State I Am In, שיר הפתיחה, הוא סיפור ארוך ומקסים שנבנה לאט. Expectations מספר על נערה שלא מתאימה לבית הספר, ו־Electronic Renaissance מפתיע עם סינתיסייזרים וקצב אלקטרוני, כמעט בדיחה על כל השאר.''',
'''Tigermilk הניח את היסודות ללהקה שהפכה לאחת האהובות בעולם האינדי, ולצליל שהשפיע על דור שלם של להקות שקטות ורגישות. רק כמה חודשים אחר כך הוציאה הלהקה את If You're Feeling Sinister (אלבום 836), שנחשב לאלבום הטוב שלה. גם השם של הלהקה הוא סיפור קטן: הוא לקוח מספר ילדים צרפתי על ילד וכלבו הגדול.''',
'''אם אהבתם את הסמית׳ס (אלבום 584), תמצאו כאן אותה רגישות, אבל בלי הכעס. שמעו את The State I Am In בשקט, והקשיבו למילים, שהן חצי מהקסם.''',
], [
('The State I Am In', 'סיפור ארוך ומקסים שנבנה לאט, עם גיטרה אקוסטית וקול לוחש.'),
('Expectations', 'שיר עדין על נערה שלא מתאימה לבית הספר, עם צ׳לו ופסנתר.'),
('Electronic Renaissance', 'הפתעה אלקטרונית קופצנית, שונה לגמרי מכל שאר האלבום.'),
])

add(816, [
'''די ג׳יי שאדו, ג׳וש דייוויס, גדל בדייוויס שבקליפורניה, ובילה את נעוריו בחנויות תקליטים משומשים, בחיפוש אחרי תקליטים נשכחים של פאנק, סול, ג׳אז ופסקולים. הוא בנה מהם קטעי היפ הופ, ו־Endtroducing, שיצא בסוף 1996 בחברה הבריטית מו׳ וואקס, היה אלבום הבכורה שלו. מה שמיוחד בו הוא שכמעט כל צליל בו לקוח מתקליטים אחרים: ספר השיאים של גינס אף ציין אותו כאחד האלבומים הראשונים שנבנו כולם מדגימות.''',
'''שאדו עבד עם מכשיר דגימה פשוט ופטיפונים, וחיבר פיסות קטנות של תופים, פסנתר, שירה וכלי מיתר לקטעים ארוכים, קולנועיים ומלאי רגש. המוזיקה נשמעת כמו פסקול לסרט שלא קיים: לפעמים אפלה ומאיימת, לפעמים עצובה ויפה, לפעמים מצחיקה. Building Steam with a Grain of Salt פותח עם פסנתר מלנכולי וקול מדבר על זמן ועל מוזיקה. Midnight in a Perfect World הוא קטע לילי ויפה, עם תופים איטיים וקול נשי מרחף. Organ Donor קצר ושובב, עם עוגב שמתפרע, ו־Stem/Long Stem הוא מסע ארוך ומשתנה.''',
'''Endtroducing הראה שאפשר ליצור יצירת אמנות שלמה, אישית ומרגשת, רק מצלילים של אחרים. הוא השפיע על ההיפ הופ האינסטרומנטלי, על הטריפ הופ ועל מוזיקאים אלקטרוניים רבים, ונחשב עד היום לאחד האלבומים החשובים של שנות התשעים. האלבום מראה גם כמה אהבה לתקליטים ישנים יכולה להפוך ליצירה חדשה לגמרי, אישית וכנה.''',
'''הקשיבו לאלבום כולו ברצף, באוזניות ובחושך, כמו לסרט. ושמעו גם את Dr. Octagonecologyst (אלבום 811), שהופק בעזרת אותו ציוד בדיוק.''',
], [
('Building Steam With a Grain of Salt', 'פסנתר מלנכולי וקול מדבר על זמן, פתיחה קולנועית ומרגשת.'),
('Midnight in a Perfect World', 'קטע לילי ויפה, עם תופים איטיים וקול נשי מרחף.'),
('Organ Donor', 'קטע קצר ושובב, עם עוגב שמשתולל מעל קצב חד.'),
])

add(817, [
'''אילז היא בעצם הלהקה של איש אחד, מארק אוליבר אוורט, שחותם בפשטות בשם E. הוא גדל בווירג׳יניה, בנו של הפיזיקאי יו אוורט, שהגה את רעיון "העולמות המקבילים" בפיזיקה, והילדות שלו הייתה מוזרה ובודדה. בתחילת שנות התשעים עבר ללוס אנג׳לס, הוציא שני אלבומי סולו שכמעט איש לא שמע, ואז הקים את אילז עם מתופף ובסיסט. Beautiful Freak, אלבום הבכורה, יצא ב־1996 בחברת התקליטים החדשה דרימוורקס, והשיר הראשון בו הפך ללהיט בכל העולם.''',
'''המוזיקה של אילז מחברת שירי פופ פשוטים ויפים עם קצבים של היפ הופ, דגימות, צלילים מוזרים וגיטרות מלוכלכות, וכל זה סביב הקול העייף והצרוד של E. השירים עוסקים בבדידות, בדיכאון, באנשים שונים ושבורים, אבל תמיד עם הומור יבש וחמלה גדולה. Novocaine for the Soul, הלהיט, הוא שיר על הרצון לא להרגיש כלום, עם מלודיה מתוקה וקצב כבד. Beautiful Freak, השיר שנתן לאלבום את שמו, הוא שיר אהבה עדין למישהי מוזרה ויפה. My Beloved Monster הוא שיר קצר, שמח ומתוק, ו־Susan's House מתאר הליכה ברחובות עצובים של לוס אנג׳לס.''',
'''Beautiful Freak פתח לאילז קריירה ארוכה, ו־E כתב בהמשך אלבומים אישיים מאוד, במיוחד אחרי שאיבד את כל משפחתו הקרובה בתוך כמה שנים. הוא נשאר אמן שמדבר בגלוי על כאב, אבל תמיד עם חיוך קטן. My Beloved Monster הופיע גם בסרט המצויר שרק, וכך הכירו אותו גם ילדים רבים.''',
'''שמעו את Novocaine for the Soul, ושימו לב לניגוד בין המלודיה המתוקה לבין המילים העצובות: זה כל הסוד של אילז. ואחר כך עברו ל־My Beloved Monster, כדי לחייך.''',
], [
('Novocaine for the Soul', 'מלודיה מתוקה וקצב כבד, על הרצון לא להרגיש כלום.'),
('Beautiful Freak', 'שיר אהבה עדין ועצוב למישהי מוזרה, שונה ויפה.'),
('My Beloved Monster', 'שיר קצר, שמח ומתוק, על אהבה למפלצת אהובה.'),
])

add(818, [
'''דה דיוויין קומדי היא בעצם ניל הנון, זמר וכותב שירים מצפון אירלנד, בנו של בישוף, שהקים את הלהקה כבר בסוף שנות השמונים. בתחילת דרכו ניגן פופ גיטרות רגיל, אבל אז מצא את הסגנון שלו: שירים גדולים ותיאטרליים, עם תזמורת, פסנתר ושירה בסגנון של זמרי השישים, כמו סקוט ווקר (אלבומים 130 ו־171). Casanova, שיצא ב־1996, היה האלבום הרביעי שלו, והראשון שהצליח באמת, עם כמה להיטים במצעד הבריטי.''',
'''האלבום כולו בנוי סביב דמות של מאהב מתוחכם, אירוני ומצחיק, והנון נהנה לשחק אותה: הוא שר בקול עמוק ומפתה, עם חיוך שמורגש בכל מילה. יש כאן כלי מיתר, כלי נשיפה, פסנתר ואפילו צלילים של מוזיקה מסרטים צרפתיים. Something for the Weekend, הלהיט הגדול, הוא סיפור מצחיק על פיתוי שהולך לא בדיוק כמו שתוכנן. Becoming More Like Alfie מתאר גבר שמתחיל להתנהג כמו גיבור סרט ישן ומפורסם, ו־Songs of Love הוא שיר יפה ונוגה, שהפך לשיר הפתיחה של סדרת הטלוויזיה האירית האהובה Father Ted.''',
'''Casanova הפך את ניל הנון לדמות מוכרת בבריטניה, והראה שבתוך גל הבריטפופ הרועש יש מקום גם לפופ אלגנטי, חכם ותזמורתי. הנון המשיך להוציא אלבומים רבים, כתב מוזיקה לסרטים ולתיאטרון, ונשאר אחד מכותבי השירים השנונים של אירלנד.''',
'''אם אהבתם את Scott 4 של סקוט ווקר (אלבום 171), תשמעו כאן את ההשפעה הברורה שלו, אבל עם הרבה יותר הומור. המשיכו מכאן ל־A Short Album About Love (אלבום 849), שיצא שנה אחר כך.''',
], [
('Something for the Weekend', 'סיפור פיתוי מצחיק שהולך לא בדיוק כמו שתוכנן, עם פזמון סוחף.'),
('Becoming More Like Alfie', 'גבר שמתחיל להתנהג כמו גיבור סרט ישן, בקצב קופצני.'),
('Songs of Love', 'שיר יפה ונוגה, שהפך לפתיחה של סדרת טלוויזיה אירית אהובה.'),
])

add(819, [
'''פיונה אפל גדלה בניו יורק, בת לשחקן ולזמרת, והתחילה לנגן בפסנתר ולכתוב שירים כבר כילדה. כנערה בת שבע עשרה היא העבירה קלטת עם שירים שלה לחברה שעבדה בתחום, הקלטת הגיעה לחברת תקליטים, ושנה אחר כך, ב־1996, יצא Tidal, אלבום הבכורה שלה, כשהיא בת שמונה עשרה בלבד. השירים נשמעו בוגרים בהרבה מגילה: עמוקים, כועסים, פגיעים ומלאי ביטחון בבת אחת. האלבום נמכר במיליוני עותקים, והיא זכתה בפרס גראמי.''',
'''הלב של האלבום הוא הפסנתר של אפל, שמנגן אקורדים כבדים ומלאי ג׳אז, והקול שלה, עמוק, חם ונמוך מאוד לזמרת צעירה. מסביב יש תופים רכים, בס, כלי מיתר ותזמורים קטנים שמזכירים ג׳אז ישן וסול. Criminal, הלהיט הגדול, הוא שיר על אשמה ועל פיתוי, עם קצב איטי ומרשים. Shadowboxer הוא שיר שקט ובוגר על מערכת יחסים מבלבלת, ו־Sleep to Dream, שיר הפתיחה, הוא קריאה נחושה של מי שלא מוכנה עוד שיפגעו בה. המילים חכמות, מלאות דימויים מפתיעים ומילים לא רגילות.''',
'''Tidal הציג את אחת הכותבות החשובות של הדור. אפל הוציאה אחריו מעט מאוד אלבומים, עם הפסקות של שנים ביניהם, אבל כל אחד מהם זכה להערכה גדולה, ואלבום שהוציאה ב־2020 נחשב לאחד הטובים של השנה. היא נשארה אמנית עקשנית, שעושה רק מה שהיא מאמינה בו.''',
'''השוו את אפל לאלאניס מוריסט (אלבום 807) ולטורי איימוס (אלבום 727): שלוש זמרות צעירות עם כעס דומה, וקולות שונים לגמרי. שמעו את Criminal ושימו לב לפסנתר הכבד.''',
], [
('Criminal', 'שיר איטי ומרשים על אשמה ועל פיתוי, עם פסנתר כבד וקול עמוק.'),
('Shadowboxer', 'שיר שקט ובוגר על מערכת יחסים מבלבלת, עם אקורדים של ג׳אז.'),
('Sleep to Dream', 'פתיחה נחושה וכועסת של מי שלא מוכנה עוד שיפגעו בה.'),
])

add(820, [
'''ג׳ף טווידי ניגן בתחילת דרכו בלהקה אנקל טופלו, אחת הלהקות שהמציאו את "האלט קאנטרי", שילוב של קאנטרי אמריקאי ישן עם אנרגיה של פאנק. כשהלהקה התפרקה ב־1994, הוא הקים את ווילקו עם רוב חבריה, והאלבום הראשון שלהם היה אלבום קאנטרי רוק צנוע. אבל Being There, שיצא ב־1996, היה קפיצה גדולה: אלבום כפול, עם תשעה עשר שירים, שבו טווידי פתח את המוזיקה לכיוונים חדשים, והראה שהוא אחד מכותבי השירים המעניינים של אמריקה.''',
'''האלבום עובר בין סגנונות רבים: קאנטרי עדין עם גיטרה אקוסטית ומנדולינה, רוק רועש ומחוספס, פופ של השישים עם קלידים וכלי נשיפה, ובלדות שקטות ועייפות. טווידי שר בקול רך ופגיע, ומרבה לכתוב על מוזיקה עצמה, על להיות בלהקה, על חלומות ועל אכזבות. Misunderstood, שיר הפתיחה, מתחיל ברעש ובכאוס ונבנה לבלדה כואבת ויפה. Monday הוא רוקנרול שמח עם כלי נשיפה בסגנון הרולינג סטונז, ו־Far, Far Away הוא שיר קאנטרי שקט ומתגעגע.''',
'''Being There היה האלבום שבו ווילקו הפסיקו להיות "הלהקה של הבחור מאנקל טופלו" והפכו ללהקה עם קול משלה. בהמשך הם הוציאו אלבומים ניסיוניים יותר, והפכו לאחת הלהקות החשובות של הרוק האמריקאי בעשורים הבאים, עם קהל נאמן מאוד. רבים חושבים שזה האלבום שבו טווידי מצא סוף סוף את הקול שלו ככותב, עם שירים שמדברים בגלוי על הספקות שלו.''',
'''תשעה עשר שירים זה הרבה בבת אחת, אז אפשר לשמוע את האלבום בשני חלקים, כמו שני התקליטים המקוריים. התחילו ב־Misunderstood, ושימו לב איך הרעש בהתחלה הופך לשיר יפה.''',
], [
('Misunderstood', 'מתחיל ברעש ובכאוס, ונבנה לבלדה כואבת ויפה על להיות לא מובן.'),
('Monday', 'רוקנרול שמח ורועש עם כלי נשיפה, כמו ערב בבר.'),
('Far, Far Away', 'שיר קאנטרי שקט ומתגעגע, עם גיטרה אקוסטית וקול רך.'),
])

add(821, [
'''ספולטורה היא להקת מטאל מבלו הוריזונטה שבברזיל, שהקימו באמצע שנות השמונים שני אחים צעירים, מקס ואיגור קבלרה. בתחילת דרכה היא ניגנה מטאל מהיר ואגרסיבי, ועם Arise (אלבום 700) הפכה לאחת להקות המטאל החשובות בעולם. ב־1996 הוציאה את Roots, אלבום שבו עשתה משהו שאיש לא עשה לפניה: היא חזרה לשורשים הברזילאיים שלה, והכניסה לתוך המטאל הכבד תופים של מוזיקה עממית ברזילאית, ואפילו מוזיקה של עם ילידי מיערות האמזונס.''',
'''הצליל של Roots כבד, איטי ונמוך יותר מבעבר, עם גיטרות מכוונות נמוך מאוד וקצבים שבטיים ועמוקים. יש כאן כלי הקשה ברזילאיים, וחלק מהאלבום הוקלט עם בני שבט השאוונטה, בכפר שלהם בברזיל, שבו הלהקה ביקרה והקליטה איתם שירה ותופים. Roots Bloody Roots, שיר הפתיחה, הוא אחד משירי המטאל המפורסמים של העשור, עם ריף אדיר וקריאה לגאווה בשורשים. Ratamahatta, עם המוזיקאי הברזילאי קרלינייוס בראון, משלב תופי סמבה עם מטאל, ו־Attitude כבד ומקפיץ.''',
'''Roots השפיע מאוד על להקות הנו מטאל של סוף שנות התשעים, ששילבו קצבים ונמוכים כבדים בדומה. זה היה גם האלבום האחרון של מקס קבלרה עם הלהקה: זמן קצר אחרי צאתו הוא עזב, ושני האחים לא ניגנו יחד במשך שנים רבות. האלבום גם הראה שמטאל יכול להיות מוזיקה של מקום מסוים ושל תרבות מסוימת, ולא רק רעש אוניברסלי.''',
'''שימו לב לרגעים שבהם המטאל נעצר ונשארים רק התופים והשירה של השבט, ואחר כך הכל חוזר בעוצמה. והשוו את האלבום ל־Arise (אלבום 700), כדי לשמוע כמה הלהקה השתנתה.''',
], [
('Roots Bloody Roots', 'ריף אדיר וקריאה לגאווה בשורשים, אחד משירי המטאל המפורסמים של העשור.'),
('Ratamahatta', 'תופי סמבה ברזילאיים פוגשים מטאל כבד, עם קרלינייוס בראון.'),
('Attitude', 'קצב כבד ומקפיץ עם גיטרות נמוכות וצעקה זועמת.'),
])

add(822, [
'''בארי אדמסון גדל במוס סייד, שכונה קשה במנצ׳סטר, והתחיל את דרכו כבסיסט של להקת הפוסט פאנק מגזין (אלבום 408). אחר כך ניגן בלהקה של ניק קייב, הבאד סידס, ובסוף שנות השמונים התחיל לעבוד לבד, עם רעיון מקורי: אלבומים שהם פסקולים לסרטים שלא קיימים. Moss Side Story (אלבום 654) היה הראשון שבהם, ו־Oedipus Schmoedipus, שיצא ב־1996, ממשיך את הרעיון, הפעם עם יותר שירה, יותר הומור, ויותר אורחים מפורסמים. אדמסון עצמו תיאר את האלבום כמסע פסיכולוגי מצחיק ואפל על יחסים בין אמהות לבנים.''',
'''המוזיקה נשמעת כמו פסקול של סרט מתח משנות השישים או השבעים, עם כלי נשיפה, כלי מיתר, בס עמוק, אורגן, ג׳אז קריר, ופה ושם גם קצבים של היפ הופ וצלילים אלקטרוניים. הכל אלגנטי, אפל ומלא קריצות. Set the Controls for the Heart of the Pelvis, שהשם שלו צוחק על שיר מפורסם של פינק פלויד, מושר על ידי ג׳רוויס קוקר מפאלפ (אלבום 802), בקול מפתה ומצחיק. The Sweetest Embrace, עם ניק קייב, הוא בלדה אפלה ויפה, ו־Dirty Barry הוא קטע ארוך וחושני, עם קצב איטי וכלי נשיפה.''',
'''אדמסון אף פעם לא הפך לכוכב גדול, אבל הוא מוערך מאוד בקרב מוזיקאים ובמאים. דייוויד לינץ׳ השתמש במוזיקה שלו בסרט Lost Highway, והוא כתב מוזיקה לסרטים רבים, וגם ביים בעצמו. Oedipus Schmoedipus נחשב לחלק השלישי של "טרילוגיה" שהתחילה ב־Moss Side Story.''',
'''שמעו את האלבום כמו סרט: עצמו עיניים, ודמיינו את הסצנות. והשוו את Set the Controls for the Heart of the Pelvis לשירים של ג׳רוויס קוקר ב־Different Class (אלבום 802).''',
], [
('Set the Controls for the Heart of the Pelvis', 'ג׳רוויס קוקר שר בקול מפתה ומצחיק, מעל פסקול של סרט מתח.'),
('The Sweetest Embrace', 'בלדה אפלה ויפה עם ניק קייב, כמו סוף של סרט עצוב.'),
('Dirty Barry', 'קטע ארוך וחושני, עם קצב איטי, בס עמוק וכלי נשיפה.'),
])

add(823, [
'''פאן לאבין קרימינלז הם שלישייה מניו יורק, שהזמר שלה, יואי מורגן, שירת בעבר בצבא האמריקאי לפני שהפך למוזיקאי. הם התחילו לנגן בתחילת שנות התשעים במועדונים של מנהטן, ו־Come Find Yourself, אלבום הבכורה שלהם, יצא ב־1996. באמריקה הוא כמעט לא הצליח, אבל בבריטניה ובאירופה הוא הפך ללהיט גדול, והלהקה הפכה לאהובה במיוחד על הקהל הבריטי, הרבה יותר מאשר בעיר הולדתה.''',
'''הצליל מחבר דברים שלא נראים קשורים: היפ הופ, רוק, בלוז, פאנק, ג׳אז, ומוזיקת לאונג׳ חלקה של פעם. מורגן לא ממש שר ולא ממש עושה ראפ, אלא מדבר בקול נמוך ורגוע, כמו גנגסטר מסרט, מעל גיטרות מחוספסות וקצבים נינוחים. Scooby Snacks, הלהיט הגדול, משלב דיאלוגים מתוך סרטים של קוונטין טרנטינו, ומספר על שוד בנק בהומור שחור. The Fun Lovin' Criminal, שיר הפתיחה, הוא הצגה עצמית שמחה ובטוחה. King of New York הוא שיר אפל על העולם התחתון של ניו יורק, ו־We Have All the Time in the World הוא גרסה מפתיעה לשיר שלואי ארמסטרונג שר בסרט של ג׳יימס בונד.''',
'''Come Find Yourself הוא אלבום של מסיבות, של מכונית פתוחה ושל לילה בעיר, והוא נשמע כמו שנות התשעים בניו יורק, דרך העיניים של מי שאוהב את סרטי הגנגסטרים של פעם. יואי מורגן המשיך גם לקריירה כמגיש רדיו אהוב בבריטניה.''',
'''שמעו את Scooby Snacks, ונסו לזהות את הקטעים מסרטי טרנטינו. ואחר כך שמעו את We Have All the Time in the World, והשוו לגרסה המקורית של לואי ארמסטרונג.''',
], [
('Scooby Snacks', 'הלהיט הגדול, עם דיאלוגים מסרטי טרנטינו וסיפור שוד בהומור שחור.'),
("The Fun Lovin' Criminal", 'הצגה עצמית שמחה ובטוחה, עם גיטרה מחוספסת וקול נינוח.'),
('King of New York', 'שיר אפל על העולם התחתון של העיר, בקצב איטי וקול נמוך.'),
])

add(824, [
'''מקסוול, ג׳רלד מקסוול ריברה, גדל בברוקלין, ממשפחה עם שורשים בפוארטו ריקו ובהאיטי. הוא שר בכנסייה כילד, ובגיל שבע עשרה התחיל ללמד את עצמו לנגן ולכתוב, בעזרת קלידים זולים. את אלבום הבכורה שלו הוא הקליט כבר ב־1994, אבל חברת התקליטים לא האמינה בו והשאירה אותו על המדף כמעט שנתיים. כשהוא סוף סוף יצא, באביב 1996, הוא הפך לאט להצלחה גדולה, נמכר במיליון עותקים ויותר, והיה מועמד לגראמי.''',
'''Maxwell's Urban Hang Suite הוא אלבום רעיוני: כל השירים יחד מספרים סיפור אהבה אחד, מהפגישה הראשונה ועד ההצעה לנישואים. מקסוול עבד עם מוזיקאים ותיקים מעולם הסול של שנות השבעים, ביניהם ליאון וור, שכתב שירים עם מרווין גיי, והצליל חם, איטי ומפתה, עם בס עמוק, גיטרות רכות ופסנתר חשמלי. הקול שלו קל ומרחף, ולעתים קרובות עולה לפלסט גבוה ועדין. Ascension (Don't Ever Wonder) הוא הלהיט, עם גרוב שמח וזורם. Sumthin' Sumthin' הוא שיר חושני ורגוע, ו־Whenever Wherever Whatever הוא בלדה קצרה ויפה, עם גיטרה אקוסטית וקול לוחש.''',
'''יחד עם דיאנג׳לו וה־Brown Sugar שלו (אלבום 804), מקסוול היה מהקולות הראשונים של הניאו סול, גל של זמרים שחזרו לסול החם והאורגני של מרווין גיי ואל גרין. הוא המשיך לקריירה ארוכה, עם הפסקות ארוכות בין אלבום לאלבום, ונשאר אחד הזמרים הרומנטיים של דורו.''',
'''שמעו את האלבום לפי הסדר, כמו סיפור, ובערב רגוע. והשוו אותו ל־Let's Get It On של מרווין גיי (אלבום 281), שהיה ברור אחד ממקורות ההשראה שלו.''',
], [
("Ascension (Don't Ever Wonder)", 'הלהיט הגדול, גרוב שמח וזורם עם קול גבוה ומרחף.'),
("Sumthin' Sumthin'", 'שיר חושני ורגוע, עם בס עמוק ופסנתר חשמלי חם.'),
('Whenever Wherever Whatever', 'בלדה קצרה ויפה עם גיטרה אקוסטית וקול לוחש.'),
])

add(825, [
'''הצ׳רלטנז היא להקה מצפון מערב אנגליה, שהתפרסמה ב־1990, בימים של סצנת המדצ׳סטר והלהקות של מנצ׳סטר, כמו הסטון רוזס (אלבום 647) וההפי מאנדייז (אלבום 619). הזמר טים ברג׳ס, עם התספורת הבלונדינית והקול הנערי, והאורגן החם של רוב קולינס היו סימני ההיכר שלה. בזמן ההקלטות של Tellin' Stories, בקיץ 1996, נהרג קולינס בתאונת דרכים. הלהקה החליטה להמשיך, ובעזרת מרטין דאפי מפריימל סקרים השלימה את האלבום, שיצא באביב 1997 והגיע למקום הראשון במצעד הבריטי.''',
'''הצליל של Tellin' Stories הוא רוק בריטי שמח וקופצני, עם גיטרות מצלצלות, אורגן המונד, השפעה של הרולינג סטונז ושל בוב דילן, והרבה אופטימיות, למרות הכל. With No Shoes פותח בקצב סוחף ובקול של ברג׳ס שעולה מעל האורגן. North Country Boy, הלהיט הגדול, הוא שיר שמח וקליל על בחור מהצפון, עם פזמון שמזמין לשיר. One to Another, עם צלילים אלקטרוניים ותופים כבדים, הוא אחד השירים האחרונים שבהם ניגן קולינס, ו־How High מהיר ונמרץ. האלבום נסגר ב־Rob's Theme, קטע כלי שקט לזכרו.''',
'''Tellin' Stories היה האלבום המצליח ביותר של הצ׳רלטנז, ונחשב לאחד הטובים שלהם. הלהקה המשיכה עוד עשרות שנים, וטים ברג׳ס הפך לדמות אהובה ומוכרת בבריטניה, גם כסופר וכמי שמארגן מפגשי האזנה משותפים לאלבומים אהובים, שבהם מוזיקאים מספרים על התקליטים שלהם. המבקרים ראו בו את התשובה של הלהקה לאסון, אלבום שבוחר בחיים ובשמחה.''',
'''הקשיבו לאורגן לאורך כל האלבום, ושימו לב כמה הוא נותן לשירים חום ושמחה. והשוו ל־The Stone Roses (אלבום 647), שממנו הכל התחיל.''',
], [
('North Country Boy', 'שיר שמח וקליל על בחור מהצפון, עם פזמון שמזמין לשיר.'),
('One to Another', 'תופים כבדים וצלילים אלקטרוניים, מהשירים האחרונים של רוב קולינס.'),
('With No Shoes', 'פתיחה סוחפת, עם אורגן חם וקול נערי שעולה מעליו.'),
])

add(826, [
'''המאניק סטריט פריצ׳רס הגיעו מבלאקווד, עיירת כורים בדרום ויילס, והתפרסמו בתחילת שנות התשעים כלהקה פוליטית, כועסת ומתגרה. ב־1994 הוציאו את The Holy Bible (אלבום 777), אלבום אפל וקשה, שרוב מילותיו נכתבו על ידי הגיטריסט ריצ׳י אדוארדס. בפברואר 1995 נעלם אדוארדס, ולא נמצא מאז. שלושת החברים שנשארו התלבטו אם להמשיך, ובסוף החליטו לנסות. Everything Must Go, שיצא במאי 1996, היה האלבום הראשון שלהם בלעדיו, והפך להצלחה הגדולה ביותר שלהם.''',
'''הצליל כאן רחב, מלודי ומלא תקווה, עם גיטרות גדולות, כלי מיתר, חצוצרות וזמר, ג׳יימס דין בראדפילד, ששר בכל הכוח. כמה מהשירים עדיין נושאים מילים שכתב אדוארדס לפני היעלמותו. A Design for Life, הלהיט הגדול, הוא המנון תזמורתי ומרגש על כבוד ועל מעמד הפועלים. Kevin Carter מספר על צלם עיתונות דרום אפריקאי, שזכה בפרס על תמונה קשה מאפריקה, ולא עמד במה שראה. Australia הוא שיר רוק סוחף על הרצון לברוח הכי רחוק שאפשר, והשיר שנתן לאלבום את שמו מדבר על הצורך להתחיל מחדש.''',
'''Everything Must Go זכה בפרסי בריט כאלבום הטוב ביותר וכלהקה הטובה ביותר, והפך את המאניקס לאחת הלהקות הגדולות בבריטניה. הוא נשמע כמו אלבום של אבל שהופך לכוח, וזה מה שהפך אותו לאהוב כל כך. עד היום, A Design for Life מושר בהופעות שלהם בקול רם על ידי כל הקהל, כמו המנון.''',
'''השוו את האלבום ל־The Holy Bible (אלבום 777): אותה להקה, אבל מהחושך אל האור. התחילו ב־A Design for Life, ושימו לב לכלי המיתר.''',
], [
('A Design for Life', 'המנון תזמורתי ומרגש על כבוד ועל מעמד הפועלים, עם כלי מיתר.'),
('Kevin Carter', 'שיר על צלם עיתונות דרום אפריקאי, עם חצוצרה וקצב חד.'),
('Australia', 'רוק סוחף ומלא אנרגיה על הרצון לברוח הכי רחוק שאפשר.'),
])

add(827, [
'''אוורית׳ינג בט דה גירל הם טרייסי ת׳ורן ובן וואט, זוג שנפגש באוניברסיטה בהאל שבאנגליה בתחילת שנות השמונים, והפך לאחד הצמדים השקטים והאהובים של הפופ הבריטי. במשך שנים הם עשו מוזיקה רכה, אקוסטית וג׳אזית, כמו Idlewild (אלבום 615). בתחילת שנות התשעים חלה וואט במחלה נדירה וקשה, וכמעט מת. אחרי שהחלים, קרה משהו לא צפוי: רמיקס דאנס שעשה התקליטן טוד טרי לשיר שלהם Missing הפך ללהיט ענק בכל העולם, ופתח להם דלת חדשה לגמרי.''',
'''Walking Wounded, שיצא ב־1996, הוא התוצאה: הצמד נכנס בכל הכוח לעולם המוזיקה האלקטרונית של לונדון, עם קצבים של דראם אנד בייס וטריפ הופ, בס עמוק וצלילים קרירים, אבל השאיר את מה שהיה הכי חשוב, הקול העמוק, החם והעצוב של ת׳ורן, והשירים העדינים על אהבה, בדידות ופרידה. Wrong הוא שיר דאנס מלנכולי ויפה, על מי שתמיד טועה באהבה. Walking Wounded, השיר שנתן לאלבום את שמו, רץ על קצב ג׳אנגל מהיר, בזמן שהקול נשאר שקט ואיטי. Single הוא שיר לילי ובודד, עם קצב טריפ הופ איטי, ו־The Heart Remains a Child נוגע ללב.''',
'''המעבר הזה, מפופ אקוסטי למוזיקה אלקטרונית, נחשב לאחד השינויים המוצלחים בתולדות הפופ הבריטי. Walking Wounded נמכר היטב והשפיע על זמרים רבים שחיפשו דרך לחבר בין שירה אישית לבין קצבים של מועדונים. ת׳ורן ווואט המשיכו בהמשך גם לקריירות סולו, וגם כתבו ספרים מצליחים.''',
'''השוו את Walking Wounded לטריפ הופ של Dummy של פורטיסהד (אלבום 761) ו־Protection של מאסיב אטאק (אלבום 776), שבו ת׳ורן שרה בשיר הנושא. ושימו לב איך הקול שלה נשאר רגוע מעל הקצב המהיר.''',
], [
('Wrong', 'שיר דאנס מלנכולי ויפה, על מי שתמיד טועה באהבה.'),
('Walking Wounded', 'קצב ג׳אנגל מהיר, וקול שקט ואיטי שמרחף מעליו.'),
('Single', 'שיר לילי ובודד, עם קצב טריפ הופ איטי ובס עמוק.'),
])

add(828, [
'''ניק קייב והבאד סידס הוציאו כבר כמה אלבומים מצליחים, כמו Henry's Dream (אלבום 731), כשב־1996 החליטו לעשות משהו מוזר במיוחד: אלבום שלם שבו כל השירים הם בלדות על רצח. בלדות כאלה הן מסורת עתיקה של שירי עם באנגליה, בסקוטלנד ובאמריקה, שבהן מספרים בפרטים על פשעים ועל נקמות, וקייב, שתמיד אהב סיפורים אפלים, לקח את המסורת הזאת ושיחק בה. חלק מהשירים הם שירי עם ישנים, וחלקם שירים חדשים שכתב בעצמו.''',
'''Murder Ballads הוא אלבום תיאטרלי, אפל ולעתים קרובות מצחיק באופן מוזר, עם פסנתר, אורגן, כינור וגיטרות, וקייב כמספר סיפורים שמדבר ושר. השיר המפורסם ביותר הוא Where the Wild Roses Grow, דואט עדין ויפה עם זמרת הפופ האוסטרלית קיילי מינוג, שהפתיע את כולם והפך ללהיט ענק. Henry Lee, דואט נוסף, הפעם עם PJ הארווי, מבוסס על שיר עם ישן, ויש בו רוך מפתיע. Stagger Lee הוא גרסה פרועה ומצחיקה לשיר אמריקאי עתיק על פושע אגדי. האלבום נסגר ב־Death Is Not the End, שיר של בוב דילן, שבו שרים יחד כמה מהאורחים, וזה סיום רך ומלא תקווה.''',
'''Murder Ballads הפך לאלבום המצליח ביותר של קייב עד אז, בזכות הדואט עם קיילי מינוג, והביא אליו קהל חדש לגמרי. הוא נשאר יוצא דופן גם ביצירה של קייב, שהאלבום הבא שלו היה שקט ואישי לגמרי.''',
'''השוו בין Murder Ballads לבין The Boatman's Call (אלבום 848), שיצא שנה אחר כך: אותו אמן, שני עולמות הפוכים. התחילו ב־Where the Wild Roses Grow, והקשיבו לשני הקולות.''',
], [
('Where the Wild Roses Grow', 'דואט עדין ויפה עם קיילי מינוג, שהפך ללהיט ענק.'),
('Henry Lee', 'דואט עם PJ הארווי, שיר עם ישן עם רוך מפתיע.'),
('Death Is Not the End', 'שיר של בוב דילן שבו שרים כמה אורחים, סיום רך ומלא תקווה.'),
])

add(829, [
'''LTJ בוקם, דני וויליאמסון, הוא תקליטן ומפיק מוואטפורד, ליד לונדון, שלמד פסנתר קלאסי כילד ואהב ג׳אז פיוז׳ן. בתחילת שנות התשעים, כשהג׳אנגל היה רועש, אפל ואגרסיבי, הוא הלך לכיוון אחר: דראם אנד בייס רך, מרחף וחלומי, שקיבל את הכינוי "אטמוספרי". הוא הקים חברת תקליטים בשם גוד לוקינג, וערב מועדון בלונדון שהפך למקום מפגש של אוהבי הסגנון. Logical Progression, שיצא ב־1996, הוא אוסף כפול שערך בוקם, עם קטעים שלו ושל אמנים נוספים מהחברה שלו, והוא הציג את הצליל הזה לקהל רחב.''',
'''המוזיקה כאן בנויה על ניגוד יפה: התופים מהירים מאוד, שבורים ומורכבים, אבל מעליהם הכל רגוע, עם פסנתר חשמלי, צלילים מרחפים של סינתיסייזר, כלי מיתר, קולות נשיים רחוקים ובס עמוק ואיטי. זה נשמע כמו ג׳אז של שנות השבעים שפוגש את המועדון של שנות התשעים. Horizons, אחד הקטעים המפורסמים של בוקם, נפתח לאט ונבנה לגל רחב ויפה. Music, עם פסנתר ושירה רחוקה, חם ומלא נשמה, ו־Demon's Theme, שפותח את האוסף, הוא קטע חלומי וארוך שמרגיש כמו שקיעה.''',
'''Logical Progression השפיע מאוד על מוזיקת הדראם אנד בייס של סוף שנות התשעים, והראה שהסגנון יכול להיות גם יפה, עדין ומרגיע. הקטעים כאן ארוכים, וכדאי לתת להם זמן, כי הם נבנים לאט ומשתנים בהדרגה. בוקם עצמו המשיך לתקלט בכל העולם במשך שנים רבות, והפך לאחד השמות המוערכים בסגנון.''',
'''זה אלבום טוב לנסיעה ארוכה או לעבודה שקטה. השוו אותו ל־Timeless של גולדי (אלבום 806), שיצא באותה תקופה, ושמעו שני צדדים שונים של אותה מוזיקה.''',
], [
('Horizons', 'נפתח לאט ונבנה לגל רחב ויפה, מעל תופים מהירים ושבורים.'),
('Music', 'פסנתר ושירה רחוקה, קטע חם ומלא נשמה מעל קצב מהיר.'),
("Demon's Theme", 'קטע פתיחה חלומי וארוך, שמרגיש כמו שקיעה איטית.'),
])

add(830, [
'''אנדרוורלד הם קארל הייד וריק סמית׳, שני מוזיקאים שעבדו יחד עוד משנות השמונים, ובתחילת שנות התשעים הצטרף אליהם התקליטן הצעיר דארן אמרסון, והלהקה הפכה לאחת החשובות במוזיקה האלקטרונית הבריטית. הייד כותב מילים מוזרות, מקוטעות, כמו פיסות שיחה שנשמעות ברחוב, ושר אותן כמו לחש או קריאה. Second Toughest in the Infants, שיצא ב־1996, היה האלבום השני שלהם בהרכב הזה, ושמו לקוח ממשפט של ילד, שסיפר שהוא "השני הכי חזק בגן".''',
'''האלבום בנוי מקטעים ארוכים, חלקם יותר מרבע שעה, שעוברים בין טכנו, דראם אנד בייס, האוס ואמביינט, ומשתנים לאט כמו מסע. Juanita/Kiteless/To Dream of Love, שפותח את האלבום, נמשך כשש עשרה דקות, ועובר בין קצבים שונים ובין רגעים של שקט. Pearl's Girl הוא אחד הקטעים האנרגטיים, עם תופים מהירים וקריאות חוזרות של הייד. Rowla מקפיץ וחד, ו־Stagger, שסוגר את האלבום, איטי, אפל ויפה, כמו עלייה לאט של השמש אחרי לילה ארוך.''',
'''באותה שנה הפך הקטע Born Slippy של אנדרוורלד ללהיט ענק, אחרי שהופיע בסיום הסרט Trainspotting, והלהקה הפכה לשם מוכר בכל העולם. Second Toughest in the Infants נחשב עד היום לאחד האלבומים הטובים של המוזיקה האלקטרונית של שנות התשעים, אלבום שמראה שאפשר לרקוד ולהקשיב בעת ובעונה אחת. גם צוות העיצוב של הלהקה, שעבד איתה על העטיפות ועל ההופעות, השפיע מאוד על האופן שבו נראתה המוזיקה האלקטרונית באותן שנים.''',
'''הקטעים כאן ארוכים, אז תנו להם זמן ושימו לב איך הם משתנים בהדרגה. השוו את אנדרוורלד ל־Leftism של לפטפילד (אלבום 803) ולאורביטל (אלבום 781).''',
], [
('Juanita: Kiteless: To Dream of Love', 'מסע של שש עשרה דקות שעובר בין קצבים שונים ורגעי שקט.'),
("Pearl's Girl", 'תופים מהירים וקריאות חוזרות, אחד הקטעים האנרגטיים באלבום.'),
('Stagger', 'סיום איטי, אפל ויפה, כמו זריחה אחרי לילה ארוך.'),
])

add(831, [
'''ג׳ון ספנסר התחיל את דרכו בסוף שנות השמונים בלהקת הנויז פאנק הרועשת פוסי גלור, ובתחילת שנות התשעים הקים בניו יורק את הבלוז אקספלוז׳ן: שלישייה עם שתי גיטרות ותופים, בלי בס בכלל. הם לקחו את הבלוז הישן, את הרוקנרול של שנות החמישים ואת הסול, ושיחקו אותם בפראות, ברעש ובהומור, כמו פאנק. Now I Got Worry, שיצא ב־1996, נחשב לאלבום הטוב שלהם, ובאותה תקופה הם גם הקליטו אלבום עם הבלוזמן הוותיק ר.ל. ברנסייד ממיסיסיפי.''',
'''האלבום מלא באנרגיה, בצעקות, בגיטרות מלוכלכות ומעוותות ובתופים חזקים, וספנסר מתנהג כמו מטיף פרוע או כמו אלביס מטורף, צועק את שם הלהקה שוב ושוב. אבל מאחורי הרעש יש הבנה עמוקה של הבלוז ושל הסול. Wail הוא רוקנרול פרוע ומדבק, עם ריף גיטרה פשוט ומושלם. Chicken Dog, עם הזמר הוותיק רופוס תומס, אחד מכוכבי הסול של ממפיס, הוא שיר מצחיק ומלא שמחה. 2 Kindsa Love מהיר ועצבני, ו־R.L. Got Soul הוא מחווה לר.ל. ברנסייד. רוב השירים קצרים, וכמעט אין רגע של שקט.''',
'''הבלוז אקספלוז׳ן השפיעו על גל של להקות גראז׳ ובלוז רוק בתחילת שנות האלפיים, כמו הווייט סטרייפס והבלאק קיז, שגם הן ניגנו בלי בס. Now I Got Worry נשאר אחד האלבומים הרועשים והשמחים של שנות התשעים. ג׳ון ספנסר עצמו המשיך גם בפרויקטים אחרים, אבל נשאר נאמן לאותה שמחה רועשת.''',
'''שמעו את האלבום בקול רם, ואל תחפשו בו שקט. ואם אהבתם את Songs the Lord Taught Us של הקרמפס (אלבום 457), תמצאו כאן אותה שמחה פרועה.''',
], [
('Wail', 'רוקנרול פרוע ומדבק, עם ריף גיטרה פשוט ומושלם.'),
('Chicken Dog', 'שיר מצחיק ומלא שמחה, עם כוכב הסול הוותיק רופוס תומס.'),
('2 Kindsa Love', 'מהיר ועצבני, עם גיטרות מעוותות וצעקות פרועות.'),
])

add(832, [
'''הקרדיגנז הם להקה מיונשופינג, עיירה בדרום שוודיה, שהקימו בתחילת שנות התשעים כמה חברים שאהבו דווקא מטאל כבד, ובראשם הגיטריסט פטר סוונסון והבסיסט מגנוס סבנינגסון. אבל כשהצטרפה אליהם הזמרת נינה פרסון, עם קול מתוק, צלול וקריר, המוזיקה שלהם הפכה לפופ רך ואלגנטי, בהשפעת מוזיקת לאונג׳ וסרטים של שנות השישים. First Band on the Moon, שיצא ב־1996, היה האלבום השלישי שלהם, והוא כלל את השיר שהפך אותם לכוכבים בכל העולם.''',
'''השיר הזה הוא Lovefool, פופ קליל ומתוק עם פזמון בלתי נשכח, שהופיע בסרט רומיאו + ג׳ולייט של באז לוהרמן והפך ללהיט ענק בכל מקום. אבל שאר האלבום מפתיע: מאחורי הצליל הנעים, עם גיטרות נקיות, כלי נשיפה, פסנתר ותופים רכים, מסתתרות מילים עצובות, מרירות ולפעמים אפלות על אהבה שלא עובדת. Your New Cuckoo פותח בקצב קופצני ושובב. Been It הוא שיר פופ חכם עם גיטרה חדה, ו־Iron Man הוא גרסה רכה ומצחיקה לשיר של בלאק סבאת׳ (אלבום 185), שמזכירה את אהבת הלהקה למטאל.''',
'''את האלבום הפיק טורה יוהנסון, באולפן שלו במאלמו, שהיה מקור לצליל מיוחד ונקי של פופ שוודי באותן שנים. הקרדיגנז המשיכו לאלבומים מצליחים נוספים, והפכו לאחת הלהקות השוודיות המוכרות בעולם מאז אבבא (אלבום 355). נינה פרסון הפכה לאחת הזמרות המוכרות של שנות התשעים, והמשיכה גם לקריירת סולו. רבים הופתעו לגלות שמאחורי הלהיט המתוק עומדת להקה עם טעם מוזיקלי רחב ומפתיע.''',
'''שמעו את Lovefool, ואחר כך את Iron Man, והשוו לגרסה המקורית של בלאק סבאת׳ ב־Paranoid (אלבום 185): אותו שיר, ושני עולמות שונים לגמרי.''',
], [
('Lovefool', 'פופ קליל ומתוק עם פזמון בלתי נשכח, הלהיט שכבש את העולם.'),
('Your New Cuckoo', 'פתיחה קופצנית ושובבה, עם כלי נשיפה ומילים מרירות.'),
('Iron Man', 'גרסה רכה ומצחיקה לשיר המטאל המפורסם של בלאק סבאת׳.'),
])

add(833, [
'''מרילין מנסון, בריאן וורנר, גדל באוהיו ועבר כנער לפלורידה, ובתחילת שנות התשעים הקים שם להקה שכל חבריה קיבלו שמות מחוברים משמות של כוכבת קולנוע מפורסמת ושל רוצח ידוע לשמצה, כדי להראות איך החברה האמריקאית מקדשת גם יופי וגם אלימות. טרנט רזנור מניין אינץ׳ ניילס (אלבום 783) החתים אותו בחברת התקליטים שלו, ו־Antichrist Superstar, שיצא בסוף 1996 בהפקה משותפת שלהם, הפך את מנסון לאחד האמנים המדוברים והשנויים במחלוקת באמריקה.''',
'''האלבום הוא אופרת רוק אפלה, בנויה בשלושה חלקים, שמספרת על יצור חלש ומושפל שהופך לכוכב רוק מפלצתי ומלא כוח, וזה בעצם משל על תהילה, על שליטה ועל דת. המוזיקה מחברת מטאל תעשייתי, עם גיטרות כבדות, צלילים אלקטרוניים ותופים מכניים, עם קטעים שקטים ומאיימים. The Beautiful People, הלהיט הגדול, הוא שיר כבד ומקפיץ עם ריף אדיר ומילים חריפות על יופי ועל כוח. Tourniquet איטי ואפל יותר, ו־Man That You Fear, שסוגר את האלבום, הוא בלדה כבדה ודרמטית. המילים קשות, וחלקן נועדו בכוונה להרגיז.''',
'''Antichrist Superstar הגיע למקום השלישי במצעד האמריקאי, ועורר מחאות של קבוצות דתיות ופוליטיקאים שניסו לבטל הופעות של מנסון. הוא נחשב לאחד האלבומים החשובים של המטאל התעשייתי, והשפיע על להקות רבות בסוף שנות התשעים. כדאי לדעת שמאז עלו נגד מנסון טענות קשות על התנהגותו.''',
'''אם אהבתם את The Downward Spiral של ניין אינץ׳ ניילס (אלבום 783), תשמעו כאן את טביעות האצבע של רזנור. התחילו ב־The Beautiful People.''',
], [
('The Beautiful People', 'שיר כבד ומקפיץ עם ריף אדיר ומילים חריפות על יופי ועל כוח.'),
('Tourniquet', 'איטי ואפל יותר, עם קול מאיים וגיטרות כבדות.'),
('Man That You Fear', 'בלדה כבדה ודרמטית שסוגרת את סיפור האופרה האפלה.'),
])

add(834, [
'''הפוג׳יז היו שלישייה מניו ג׳רזי: לורין היל, וויקלף ז׳אן ופראס מישל, ששניים מהם בני מהגרים מהאיטי. שמם קיצור של "פליטים", כמחווה לשורשים שלהם. האלבום הראשון שלהם כמעט לא הצליח, אבל The Score, שיצא בתחילת 1996, הפך לאחד האלבומים הנמכרים בתולדות ההיפ הופ, עם יותר מחמישה עשר מיליון עותקים בכל העולם, וזכה בפרס הגראמי לאלבום הראפ הטוב ביותר. הם הקליטו אותו באולפן קטן במרתף ביתו של דודו של וויקלף.''',
'''The Score מחבר היפ הופ עם סול, רגאיי ומוזיקה מהאיים הקריביים, עם קצבים נינוחים, דגימות חמות ושירה. לורין היל היא הלב של האלבום: היא גם ראפרית חדה ומבריקה, וגם זמרת עם קול נפלא. Killing Me Softly, גרסה לשיר המפורסם של רוברטה פלאק, הפך ללהיט ענק בכל העולם, עם קצב היפ הופ איטי והקול של היל שמרחף מעליו. Ready or Not הוא שיר אפל ודרמטי, עם דגימה משיר של אניה. Fu-Gee-La הוא שיר קליל ושמח, ו־No Woman, No Cry היא גרסה חמה לשיר של בוב מארלי (אלבום 324), שוויקלף שר.''',
'''הפוג׳יז התפרקו זמן קצר אחרי ההצלחה, ושלושתם המשיכו לבד. לורין היל הוציאה ב־1998 אלבום סולו שנחשב לאחת היצירות החשובות של התקופה, ווויקלף ז׳אן הפך למפיק מצליח. The Score נשאר אחד האלבומים האהובים של שנות התשעים, אלבום שגם מי שלא אוהב היפ הופ מוצא בו משהו.''',
'''שמעו את Killing Me Softly, ואחר כך חפשו את הגרסה המקורית של רוברטה פלאק. והשוו את No Woman, No Cry לגרסה של מארלי ב־Natty Dread (אלבום 324).''',
], [
('Killing Me Softly', 'גרסה לשיר של רוברטה פלאק, עם קצב איטי והקול הנפלא של לורין היל.'),
('Ready or Not', 'שיר אפל ודרמטי, עם דגימה משיר של אניה וראפ חד.'),
('Fu-Gee-La', 'שיר קליל ושמח, עם פזמון מתוק וקצב נינוח.'),
])

add(835, [
'''אש הם שלושה חברים מדאונפטריק, עיירה קטנה בצפון אירלנד, שהקימו את הלהקה כשהיו בני חמש עשרה בערך. הם הוציאו את הסינגלים הראשונים שלהם כשעוד למדו בבית הספר, וכשסיימו את הבחינות האחרונות, יצאו להקליט את אלבום הבכורה. 1977, שיצא ב־1996, הגיע ישר למקום הראשון במצעד הבריטי. השם שלו הוא שנת הלידה של שניים מחברי הלהקה, וגם השנה שבה יצא הסרט מלחמת הכוכבים, שהם אהבו מאוד: האלבום נפתח בצליל של חללית מהסרט.''',
'''המוזיקה היא רוק פופ צעיר, מהיר ושמח, עם גיטרות רועשות, מלודיות מתוקות ופזמונים שנדבקים, בהשפעת הפאנק, הרוק של שנות השבעים ולהקות אמריקאיות כמו נירוונה. הזמר והגיטריסט טים ווילר כותב שירים על אהבה ראשונה, על קיץ ועל חופש, ושר בקול נערי ונלהב. Girl from Mars, הלהיט הגדול, הוא שיר אהבה מתוק ומהיר על בחורה מכוכב אחר. Goldfinger איטי ואפל יותר, עם גיטרות כבדות, ו־Oh Yeah הוא שיר קיץ נוסטלגי ומרגש. Kung Fu הוא שיר פאנק קצר ומצחיק, שנכתב כמחווה לשחקן ג׳קי צ׳אן.''',
'''1977 תפס את מה שהיה הכי יפה בבריטפופ: שמחה פשוטה של להיות צעיר ולנגן בלהקה. אש המשיכו לנגן עוד שנים רבות, ונשארו להקה אהובה מאוד באירלנד ובבריטניה. את האלבום הפיק אוון מוריס, שעבד גם עם אואזיס, והוא נתן לשירים צליל גדול ורועש.''',
'''אם אהבתם את The Undertones (אלבום 438), עוד להקה צעירה מצפון אירלנד, תמצאו כאן אותה אנרגיה. שמעו את Oh Yeah בקיץ, עם החלון פתוח.''',
], [
('Girl from Mars', 'שיר אהבה מתוק ומהיר על בחורה מכוכב אחר.'),
('Oh Yeah', 'שיר קיץ נוסטלגי ומרגש, על אהבה ראשונה ועל חופש.'),
('Goldfinger', 'איטי ואפל יותר, עם גיטרות כבדות ופזמון גדול.'),
])

add(836, [
'''רק כמה חודשים אחרי Tigermilk (אלבום 815), הקליטו בל אנד סבסטיאן את האלבום השני שלהם, הפעם בחברת תקליטים אמיתית, ג׳יפסטר, ובזמן קצר. If You're Feeling Sinister יצא בסוף 1996, והלהקה עדיין כמעט לא נתנה ראיונות ולא הופיעה בתמונות, כך שהיא נשארה מסתורית, ואוהבי מוזיקה העבירו את התקליט מיד ליד כמו סוד. עם השנים הוא הפך לאחד האלבומים האהובים ביותר של האינדי הבריטי, ורבים חושבים שהוא הטוב ביותר שלהם.''',
'''המוזיקה עדינה, אקוסטית ומלאה בהשפעות מפופ של שנות השישים: גיטרות, פסנתר, חצוצרה, צ׳לו, מפוחית וקולות רכים. סטיוארט מרדוק כותב סיפורים קטנים על דמויות צעירות ובודדות, על דת, על בית ספר, על אהבה ועל מבוכה, עם הומור עדין ועצב שקט. The Stars of Track and Field, שיר הפתיחה, מתאר אתלטים צעירים ויפים מנקודת מבט של מי שמסתכל מהצד. Me and the Major הוא שיר מצחיק וקופצני, עם מפוחית, על שיחה בין צעיר לבין אדם מבוגר מדור אחר. Get Me Away from Here, I'm Dying הוא שיר שמח על תחושה של מי שמרגיש שהמוזיקה מצילה אותו. Judy and the Dream of Horses סוגר את האלבום ברוך.''',
'''If You're Feeling Sinister הפך לאבן דרך לדור שלם של להקות שקטות, רגישות ואינטליגנטיות, בכל העולם. בל אנד סבסטיאן המשיכו לקריירה ארוכה ואהובה.''',
'''הקשיבו למילים, שהן חצי מהקסם, ושימו לב כמה סיפורים מסתתרים בתוך שירים קטנים ושקטים. והשוו לאלבום הקודם, Tigermilk (אלבום 815).''',
], [
('The Stars of Track and Field', 'פתיחה עדינה ומרגשת על אתלטים צעירים, מנקודת מבט של מי שמסתכל מהצד.'),
('Me and the Major', 'שיר מצחיק וקופצני עם מפוחית, על שיחה בין שני דורות.'),
("Get Me Away from Here, I'm Dying", 'שיר שמח על מוזיקה שמצילה, עם כלי נשיפה ופזמון מתוק.'),
])

add(837, [
'''באמצע שנות התשעים בלר היו אחת הלהקות הגדולות בבריטניה, עם Parklife (אלבום 772) ושירים על החיים האנגליים, אבל חברי הלהקה התעייפו מהבריטפופ ומהתחרות עם אואזיס. הגיטריסט גרהאם קוקסון התאהב בלהקות אינדי אמריקאיות מחוספסות כמו פייבמנט (אלבום 708), והזמר דיימון אלברן הסכים לנסות כיוון חדש. האלבום שנקרא פשוט Blur, ויצא בתחילת 1997, הוקלט בחלקו ברייקיאוויק שבאיסלנד, ונשמע אחר לגמרי ממה שהקהל הכיר: מלוכלך, משוחרר, עצוב וניסיוני יותר.''',
'''במקום פופ מלוטש ודמויות אנגליות מצחיקות, יש כאן גיטרות רועשות ומעוותות, הקלטות שנשמעות כמעט ביתיות, שירים איטיים ועייפים ורגעים של רעש. אלברן כתב שירים אישיים יותר, על תקופה קשה בחייו ועל מערכת יחסים מסובכת. Beetlebum, שפותח את האלבום, הוא שיר איטי, מנומנם ויפה, עם גיטרה מתפתלת, והוא הגיע למקום הראשון במצעד הבריטי. Song 2 הוא שיר קצר, רועש ומצחיק של כשתי דקות, עם קריאת "וו־הו" שכל העולם מכיר. On Your Own הוא שיר שמח ומבולגן עם צלילים אלקטרוניים, ו־M.O.R. שואל בגלוי ממוזיקה של דייוויד בואי.''',
'''Song 2 הפך ללהיט ענק דווקא באמריקה, שבה הלהקה כמעט לא הצליחה קודם, והופיע מאז באינספור משחקי וידאו, אירועי ספורט ופרסומות. האלבום הוכיח שבלר הם לא רק להקת בריטפופ, אלא להקה שמסוגלת להשתנות, והוביל אותם לשנים של ניסיונות נוספים. דיימון אלברן הקים בהמשך את גורילז.''',
'''השוו את Beetlebum ל־Parklife (אלבום 772) כדי לשמוע כמה הלהקה השתנתה בשלוש שנים, ואחר כך שמעו את Crooked Rain, Crooked Rain של פייבמנט (אלבום 760), שהשפיע על הצליל החדש.''',
], [
('Beetlebum', 'שיר איטי, מנומנם ויפה, עם גיטרה מתפתלת וקול עייף.'),
('Song 2', 'שתי דקות של רעש ושמחה, עם קריאת "וו־הו" שכל העולם מכיר.'),
('On Your Own', 'שיר שמח ומבולגן, עם צלילים אלקטרוניים ופזמון סוחף.'),
])

add(838, [
'''רדיוהד מאוקספורד כבר הוכיחו את עצמם עם The Bends (אלבום 797), אבל OK Computer, שיצא באביב 1997, הפך אותם לאחת הלהקות החשובות בעולם. את רוב האלבום הם הקליטו לא באולפן רגיל אלא באחוזה עתיקה ליד העיר באת׳, יחד עם המפיק נייג׳ל גודריץ׳, שהמשיך לעבוד איתם מאז. השירים עוסקים בעולם מודרני מהיר, קר וטכנולוגי, בניכור, בנסיעות, במחשבים ובפחד, ונשמעו כמעט כמו נבואה על העולם שהגיע אחר כך.''',
'''המוזיקה עדיין רוק של גיטרות, אבל מלאה בצלילים חדשים: קלידים, כלי מיתר, צלילים אלקטרוניים, מלוטרון וקולות מעובדים. הזמר תום יורק שר בקול גבוה, שביר ומלא חרדה. Paranoid Android, באורך של יותר משש דקות, בנוי מכמה חלקים שונים לגמרי, מגיטרה אקוסטית שקטה ועד פיצוץ רועש ומקהלה עצובה. Karma Police הוא שיר איטי עם פסנתר ופזמון שמושר יחד, ו־No Surprises הוא שיר עדין כמו שיר ערש, עם פעמונים מנצנצים, על חיים שקטים מדי. Exit Music (For a Film) נכתב לסרט רומיאו + ג׳ולייט. ובאמצע האלבום יש את Fitter Happier, קול מחשב קר שמקריא רשימה של עצות לחיים "בריאים".''',
'''OK Computer זכה בגראמי, נבחר שוב ושוב ברשימות של האלבומים הטובים בכל הזמנים, והשפיע על דור שלם של להקות. רדיוהד המשיכו משם לניסויים נועזים עוד יותר, עם מוזיקה אלקטרונית וג׳אז.''',
'''שמעו את האלבום כולו ברצף, באוזניות, ולפי הסדר: הוא בנוי כמו מסע אחד. השוו אותו ל־The Bends (אלבום 797) כדי לשמוע את הקפיצה הגדולה.''',
], [
('Paranoid Android', 'כמה שירים בשיר אחד, מגיטרה אקוסטית שקטה ועד פיצוץ ומקהלה עצובה.'),
('Karma Police', 'שיר איטי עם פסנתר ופזמון שמושר יחד, ואווירה מאיימת.'),
('No Surprises', 'שיר עדין כמו שיר ערש, עם פעמונים מנצנצים, על חיים שקטים מדי.'),
])

add(839, [
'''פינלי קוואיי גדל באדינבורו שבסקוטלנד, בנו של מוזיקאי ג׳אז, ובמשפחה מוזיקלית במיוחד: הוא דודו של טריקי (אלבום 789), למרות שהוא צעיר ממנו. הוא אהב רגאיי, סול, בלוז וג׳אז, וחיבר ביניהם בדרך משלו. Maverick a Strike, אלבום הבכורה שלו, יצא ב־1997, הפך להצלחה גדולה בבריטניה, ובשנה שאחריה זכה קוואיי בפרס בריט לזמר הבריטי הטוב ביותר. הוא היה אחד הקולות המקוריים והחמים של הפופ הבריטי של סוף שנות התשעים.''',
'''הלב של האלבום הוא רגאיי רך ושמשי, אבל סביבו יש סול, גיטרות בלוז, צלילים של טריפ הופ, כלי נשיפה ותופים נינוחים. קוואיי שר בקול גבוה, רך ומעט צרוד, שמזכיר זמרי רגאיי מג׳מייקה של שנות השבעים. Even After All, הלהיט הגדול, הוא שיר אהבה קליל ושמח, עם קצב רגאיי ופזמון שנדבק. Sunday Shining הוא שיר שמש מתוק, שמבוסס על שיר של בוב מארלי, ו־It's Great When We're Together הוא שיר רך ונינוח על האושר הפשוט של להיות יחד. Ultra Stimulation, שפותח את האלבום, מחוספס ועוצמתי יותר, עם גיטרות ותופים כבדים.''',
'''Maverick a Strike היה האלבום המצליח ביותר של קוואיי. הוא המשיך להוציא תקליטים, אבל אף אחד מהם לא הגיע להצלחה של הבכורה. האלבום נשאר דוגמה יפה לאופן שבו הרגאיי השתלב במוזיקה הבריטית, כמו שקרה עשרים שנה קודם עם להקות הפאנק.''',
'''זה אלבום מושלם לבוקר של שבת עם שמש. השוו את Sunday Shining לשיר המקורי של בוב מארלי, ואת קוואיי לאחיין שלו, טריקי, ב־Maxinquaye (אלבום 789).''',
], [
('Even After All', 'שיר אהבה קליל ושמח עם קצב רגאיי ופזמון שנדבק.'),
('Sunday Shining', 'שיר שמש מתוק, שמבוסס על שיר של בוב מארלי.'),
("It's Great When We're Together", 'שיר רך ונינוח על האושר הפשוט של להיות יחד.'),
])

add(840, [
'''מיסי אליוט גדלה בפורטסמות׳ שבווירג׳יניה, וכבר כילדה חלמה להיות כוכבת. יחד עם חבר הילדות שלה, המפיק טימבלנד, היא כתבה והפיקה בשנות התשעים להיטים לזמרים אחרים, ובמיוחד לזמרת אליה, לפני שהוציאה אלבום משלה. Supa Dupa Fly, שיצא בקיץ 1997, היה אלבום הבכורה שלה, והוא נכנס ישר לשלישייה הראשונה במצעד האמריקאי, הישג נדיר לראפרית באותם ימים. האלבום הפך אותה לאחת הדמויות החשובות והמקוריות בהיפ הופ.''',
'''הקצבים של טימבלנד היו משהו שאיש לא שמע קודם: שבורים, מגמגמים, מלאי שתיקות פתאומיות וצלילים מוזרים, כמו קולות של חיות, טיפות מים או רעשים מצוירים, עם בס עמוק ואיטי. מיסי עצמה עוברת בין ראפ, שירה ודיבור, עם הומור, ביטחון ושובבות. The Rain (Supa Dupa Fly), הלהיט הגדול, מבוסס על שיר סול ישן על גשם, וקצב איטי ורגוע. הקליפ שלו, שבו היא לובשת חליפת פלסטיק שחורה ומנופחת, הפך לאחד הקליפים המפורסמים של העשור. Sock It 2 Me הוא שיר קופצני ומצחיק, ו־Beep Me 911 הוא שיר רך עם שירה וקצב מוזר ומהפנט.''',
'''Supa Dupa Fly שינה את הצליל של ההיפ הופ ושל הרית׳ם אנד בלוז בסוף שנות התשעים, והשפיע על מפיקים רבים. מיסי אליוט המשיכה לאלבומים ולהיטים רבים, והייתה לראפרית הראשונה שנכנסה להיכל התהילה של כותבי השירים באמריקה.''',
'''הקשיבו באוזניות לקצבים של טימבלנד, ונסו לזהות את כל הצלילים המוזרים שמסתתרים בהם. והשוו ל־Doggystyle של סנופ (אלבום 752), כדי לשמוע כמה ההיפ הופ השתנה בארבע שנים.''',
], [
('The Rain (Supa Dupa Fly)', 'שיר איטי ונינוח על גשם, עם קצב שבור ומוזר.'),
('Sock It 2 Me', 'שיר קופצני ומצחיק, עם ראפ בטוח ופזמון שובב.'),
('Beep Me 911', 'שיר רך עם שירה וקצב מוזר ומהפנט, עם קולות של מכשירים.'),
])

add(841, [
'''הכימיקל בראדרס, טום רולנדס ואד סימונס, נפגשו בזמן הלימודים באוניברסיטה במנצ׳סטר, והתחילו לתקלט יחד במועדונים. אלבום הבכורה שלהם, Exit Planet Dust (אלבום 793), הפך אותם לשם מוכר, ו־Dig Your Own Hole, שיצא באביב 1997, הגיע למקום הראשון במצעד הבריטי. הוא היה אחד האלבומים שהביאו את המוזיקה האלקטרונית לקהל של הרוק, והם הופיעו בפסטיבלים הגדולים כמו להקת רוק לכל דבר, מול עשרות אלפי אנשים.''',
'''המוזיקה רועשת, כבדה ומלאה באנרגיה: תופים חזקים שנשמעים כמו היפ הופ, בס עבה, צלילים פסיכדליים, דגימות ופיצוצים של רעש, והכל בונה ובונה עד שיא. Block Rockin' Beats, שפותח את האלבום, הוא קצב אדיר עם קו בס מתגלגל, והוא זכה בגראמי. Setting Sun, עם נואל גלאגר מאואזיס (אלבום 805) בשירה, הוא שיר פסיכדלי וכבד בהשראת הביטלס, שהגיע למקום הראשון במצעד הבריטי. Elektrobank הוא קטע ארוך שמשתנה כל הזמן, ו־The Private Psychedelic Reel, שסוגר את האלבום, הוא מסע מהפנט של תשע דקות, עם צלילים מזרחיים.''',
'''Dig Your Own Hole נחשב לאחד האלבומים החשובים של הביג ביט, הסגנון שחיבר מוזיקה אלקטרונית עם רוק והיפ הופ, לצד פטבוי סלים (אלבום 810) והפרודיג׳י (אלבום 846). הכימיקל בראדרס המשיכו להוציא אלבומים מצליחים, ונשארו אחת הלהקות האלקטרוניות האהובות בעולם. הם גם היו מהראשונים שהראו שאמנים אלקטרוניים יכולים לעבוד עם זמרים מעולם הרוק, ולהפיק מזה שירים אמיתיים.''',
'''שמעו את האלבום בקול רם, כמעט ברצף אחד, כי הקטעים מחוברים זה לזה כמו סט של תקליטן. ושימו לב איך Setting Sun מזכיר את Tomorrow Never Knows של הביטלס.''',
], [
("Block Rockin' Beats", 'קצב אדיר עם קו בס מתגלגל, פתיחה שמזיזה כל גוף.'),
('Setting Sun', 'נואל גלאגר שר על קצב פסיכדלי וכבד, בהשראת הביטלס.'),
('The Private Psychedelic Reel', 'מסע מהפנט של תשע דקות, עם צלילים מזרחיים ובנייה איטית.'),
])

add(842, [
'''פריימל סקרים מגלזגו, בהנהגת הזמר בובי גילספי, תמיד אהבו להשתנות. אחרי Screamadelica (אלבום 705), שחיבר רוק עם מוזיקת ריקודים, הם הוציאו אלבום רוקנרול ישן וגס, ואז, ב־1997, חזרו עם Vanishing Point, אלבום אפל, אלקטרוני ומוזר בהרבה. בינתיים הצטרף אליהם הבסיסט מאני, מהסטון רוזס (אלבום 647). שם האלבום לקוח מסרט אמריקאי משנת 1971 על נהג שבורח מהמשטרה במרדף ארוך במדבר, והלהקה חשבה עליו כפסקול חלופי לסרט.''',
'''הצליל מחבר דאב ג׳מייקני עמוק, עם בס ענק והדהודים, קראוטרוק גרמני מהפנט, מוזיקה אלקטרונית ורוק פסיכדלי, והכל נשמע כמו נסיעה לילית מהירה ומסוכנת. Kowalski, על שם הנהג מהסרט, הוא קטע עם בס כבד, קצב מתוח ודגימות מהסרט. Star הוא שיר רך ושמשי, מעין גוספל נינוח עם כלי נשיפה ומלודיקה, על תקווה ועל חופש, ו־Burning Wheel, שפותח את האלבום, הוא מסע פסיכדלי של שבע דקות. יש כאן גם גרסה מהירה ורועשת לשיר של להקת המטאל מוטורהד, וגם Trainspotting, קטע איטי ומהפנט שנכתב לסרט באותו שם.''',
'''Vanishing Point הוכיח שפריימל סקרים לא מסתפקים בהצלחה של העבר, והוביל אותם לשנים של מוזיקה אפלה וניסיונית. מפיק הדאב הבריטי אדריאן שרווד אפילו הוציא אחריו גרסה שלמה מעובדת לדאב של האלבום. הוא נשמע עד היום רענן ומאיים. רבים חושבים שזה האלבום האמיץ ביותר של הלהקה, דווקא כי הוא כל כך שונה ממה שציפו ממנה.''',
'''שמעו את האלבום בלילה, ואם אפשר, ראו קודם את הסרט Vanishing Point, ודמיינו את הקטעים כפסקול שלו. והשוו ל־Screamadelica (אלבום 705).''',
], [
('Kowalski', 'בס כבד, קצב מתוח ודגימות מהסרט, כמו מרדף לילי במדבר.'),
('Star', 'גוספל נינוח ושמשי עם כלי נשיפה ומלודיקה, על תקווה ועל חופש.'),
('Burning Wheel', 'מסע פסיכדלי של שבע דקות, עם צלילים מסתחררים ובס עמוק.'),
])

add(843, [
'''רוברט וויאט היה המתופף והזמר של סופט מאשין (אלבום 194), אחת הלהקות החשובות של הרוק הניסיוני הבריטי. ב־1973 נפל מחלון בזמן מסיבה, ונשאר משותק ברגליו ומרותק לכיסא גלגלים. הוא לא הפסיק לעשות מוזיקה, ו־Rock Bottom (אלבום 325), שהקליט אחרי התאונה, נחשב לאחת היצירות היפות של שנות השבעים. אחר כך הוא הוציא אלבומים לעתים רחוקות, עם הפסקות ארוכות, ו־Shleep, שיצא ב־1997, היה החזרה שלו אחרי כמה שנים של שקט, ומבקרים רבים רואים בו את אחד הטובים שלו.''',
'''השם הוא משחק מילים על "שינה", והאלבום כולו נשמע כמו מצב שבין ערות לחלום. הקול של וויאט גבוה, שביר ורך, כמו של ילד חכם ועצוב, והמוזיקה מחברת ג׳אז, פופ, רוק עדין וצלילים מוזרים, עם פסנתר, חצוצרה, טרומבון, סקסופון וגיטרות. בין האורחים יש מוזיקאים מפורסמים כמו בריאן אינו ופול ולר. אשתו, הציירת אלפרדה בנג׳, כתבה חלק מהמילים. Heaps of Sheeps הוא שיר קופצני ומצחיק על נדודי שינה ועל ספירת כבשים. Free Will and Testament הוא שיר שקט ועמוק על חופש הבחירה, ו־Maryan הוא קטע ארוך וחלומי עם כינור.''',
'''Shleep הראה שוויאט, בן חמישים ושתיים, עדיין יכול להפתיע, ולכתוב מוזיקה רכה, מצחיקה ועמוקה בבת אחת. הוא אמן שמוזיקאים רבים מעריצים, למרות שמעולם לא היה כוכב גדול, והאלבום הזה הוא אחת הדרכים הטובות להכיר אותו.''',
'''שמעו את האלבום בערב שקט, אולי לפני השינה, כמו שהשם מציע. והשוו אותו ל־Rock Bottom (אלבום 325), שהוקלט עשרים וארבע שנים קודם.''',
], [
('Heaps of Sheeps', 'שיר קופצני ומצחיק על נדודי שינה ועל ספירת כבשים.'),
('Free Will and Testament', 'שיר שקט ועמוק על חופש הבחירה, עם קול שביר ורך.'),
('Maryan', 'קטע ארוך וחלומי, עם כינור מרחף וקצב איטי.'),
])

add(844, [
'''דייוויד הולמס הוא תקליטן ומפיק מבלפסט שבצפון אירלנד, שהתחיל לתקלט בגיל צעיר מאוד, וכבר בשנות התשעים היה אחד הדמויות המוכרות בסצנת המוזיקה האלקטרונית של העיר. הוא אהב במיוחד פסקולים של סרטי מתח משנות השישים והשבעים, ג׳אז, פאנק וסול ישנים. כשהתחיל לעבוד על Let's Get Killed, שיצא ב־1997, הוא נסע לניו יורק, הסתובב ברחובות עם מכשיר הקלטה, ואסף קולות של אנשים, שיחות, צעקות ורעשי העיר, והכניס אותם לתוך המוזיקה.''',
'''התוצאה היא אלבום שנשמע כמו פסקול לסרט מתח עירוני: קצבי היפ הופ וביג ביט, בס עמוק, כלי נשיפה, אורגן, כלי מיתר, צלילים של סרטי ריגול, ומעל הכל קולות אמיתיים מרחובות ניו יורק. My Mate Paul הוא קטע מהיר וסוחף, עם קצב רוקנרול ודגימות של כלי נשיפה. Let's Get Killed, השיר שנתן לאלבום את שמו, אפל ומאיים, עם קולות של אנשים מספרים סיפורים מהרחוב. Gritty Shaker הוא קטע פאנקי ומקפיץ, ו־Don't Die Just Yet, שסוגר את האלבום, הוא קטע יפה ומלנכולי, עם כלי מיתר ובס, שנבנה על שירים של סרז׳ גינסבורג מתוך Histoire de Melody Nelson (אלבום 226).''',
'''Let's Get Killed הפך את הולמס לשם מוכר, ובמאים בהוליווד שמו לב אליו. בשנים הבאות הוא כתב מוזיקה לסרטים מצליחים, ביניהם Ocean's Eleven של סטיבן סודרברג, והמשיך לעבוד גם על אלבומים משלו ולהפיק אמנים אחרים.''',
'''שמעו את Don't Die Just Yet, ואחר כך חזרו ל־Histoire de Melody Nelson של סרז׳ גינסבורג (אלבום 226), ונסו לזהות את המקור: הבס והמיתרים כמעט זהים.''',
], [
('My Mate Paul', 'קטע מהיר וסוחף עם קצב רוקנרול ודגימות של כלי נשיפה.'),
('Gritty Shaker', 'קטע פאנקי ומקפיץ, עם אורגן ובס עמוק.'),
("Don't Die Just Yet", 'קטע יפה ומלנכולי עם כלי מיתר, שנבנה על שיר של גינסבורג.'),
])

add(845, [
'''סלייטר־קיני הוקמה באולימפיה שבמדינת וושינגטון, באמצע שנות התשעים, מתוך סצנת הריוט גרל, תנועה של להקות פאנק של נשים צעירות שכתבו על פמיניזם, על כוח ועל חיים של בנות. שתי הגיטריסטיות והזמרות, קורין טאקר וקארי בראונסטין, ניגנו בלי בס בכלל, ושתי הגיטרות שלהן משלימות זו את זו. Dig Me Out, שיצא ב־1997, היה האלבום השלישי שלהן, והראשון עם המתופפת ג׳נט וייס, שנתנה ללהקה עוצמה חדשה. רבים רואים בו את האלבום הטוב שלהן.''',
'''הצליל חד, מהיר ומלא אנרגיה, עם שתי גיטרות שמשתלבות כמו שיחה, תופים חזקים ושני קולות שונים מאוד: טאקר שרה בקול חזק, רוטט ומלא רגש, כמעט צעקה, ובראונסטין עונה לה בקול נמוך ויבש יותר. השירים עוסקים באהבה, בפרידה, בכעס ובשמחה של לנגן רוקנרול. Dig Me Out, שיר הפתיחה, הוא קריאה סוחפת ומלאת כוח. One More Hour הוא שיר פרידה כואב, שנכתב על הסוף של מערכת יחסים בין שתי חברות הלהקה. Words and Guitar הוא שיר שמח ונלהב על אהבת המוזיקה עצמה, ו־Little Babies קופצני ומצחיק.''',
'''Dig Me Out הפך את סלייטר־קיני לאחת הלהקות החשובות של הרוק האלטרנטיבי, ומבקר אמריקאי ידוע אף כינה אותן "הלהקה הטובה באמריקה". קארי בראונסטין התפרסמה מאוחר יותר גם כשחקנית וככותבת של סדרת קומדיה.''',
'''השוו את Dig Me Out ל־Live Through This של הול (אלבום 775) ול־Rid of Me של PJ הארווי (אלבום 745): שלוש דרכים שונות לכעס נשי ברוק של שנות התשעים.''',
], [
('Dig Me Out', 'פתיחה סוחפת ומלאת כוח, עם שתי גיטרות וקול רוטט.'),
('One More Hour', 'שיר פרידה כואב, על סוף של מערכת יחסים בין שתי חברות.'),
('Words and Guitar', 'שיר שמח ונלהב על אהבת המוזיקה, עם קצב מהיר.'),
])

add(846, [
'''הפרודיג׳י התחילו בתחילת שנות התשעים כלהקת רייב מאסקס, סביב המפיק ליאם האולט, ועם Music for the Jilted Generation (אלבום 784) הפכו ללהקה אלקטרונית רצינית וכועסת. אבל The Fat of the Land, שיצא בקיץ 1997, הפך אותם לכוכבים בכל העולם: הוא הגיע למקום הראשון במצעד גם בבריטניה וגם באמריקה, הישג נדיר מאוד ללהקה אלקטרונית. הפרצוף של הלהקה היה קית׳ פלינט, הרקדן שהפך לזמר, עם תסרוקת פאנק בשני קרניים, עיניים מאופרות ואנרגיה מטורפת.''',
'''המוזיקה מחברת מוזיקה אלקטרונית עם פאנק ורוק כבד: קצבים כבדים ומהירים, גיטרות מעוותות, בס ענק, צעקות ודגימות. Firestarter, הלהיט הגדול, עם הקול המתגרה של פלינט, הגיע למקום הראשון בבריטניה ועורר מחלוקת כי נשמע לחלק מהאנשים כמו קריאה להצית. Breathe, גם הוא במקום הראשון, הוא שיר כבד ומאיים, שבו פלינט והזמר מקסים מתחלפים. Narayan, יותר מתשע דקות, משלב צלילים הודיים עם קצב כבד. שיר הפתיחה עורר סערה בגלל שמו והקליפ שלו, שנאסר לשידור במקומות רבים.''',
'''The Fat of the Land היה אחד האלבומים שהביאו את המוזיקה האלקטרונית לקהל של הרוק בכל העולם, לצד הכימיקל בראדרס (אלבום 841). קית׳ פלינט מת ב־2019, אבל השירים מהאלבום עדיין מרעידים כל מסיבה. מעט מאוד להקות אלקטרוניות הצליחו להיות גם להקות רוק אמיתיות על הבמה, והפרודיג׳י הייתה אחת מהן.''',
'''שמעו את Breathe בקול רם, ושימו לב איך שני הקולות מתחלפים. השוו את האלבום ל־Music for the Jilted Generation (אלבום 784), כדי לשמוע איך הלהקה הפכה מלהקת רייב ללהקת רוק.''',
], [
('Firestarter', 'הקול המתגרה של קית׳ פלינט מעל קצב כבד, הלהיט שכבש את בריטניה.'),
('Breathe', 'שיר כבד ומאיים, שבו שני זמרים מתחלפים מעל גיטרות ובס.'),
('Narayan', 'יותר מתשע דקות, עם צלילים הודיים מעל קצב כבד ומהיר.'),
])

add(847, [
'''הסיפור של Buena Vista Social Club מתחיל בתוכנית שנכשלה. ב־1996 הגיעו לאולפן בהוואנה הגיטריסט האמריקאי ריי קודר, שעבד קודם עם עלי פרקה טורה (אלבום 774), והמפיק הבריטי ניק גולד, כדי להקליט מוזיקאים מאפריקה יחד עם מוזיקאים קובנים. המוזיקאים מאפריקה לא הגיעו בגלל בעיות של אשרות, ובמקום לוותר, אספו בעזרת המוזיקאי הקובני חואן דה מרקוס גונזלס חבורה של מוזיקאים ותיקים, חלקם כבר בשנות השבעים והשמונים לחייהם, שנשכחו כמעט לגמרי. תוך כמה ימים הם הקליטו את האלבום כולו.''',
'''המוזיקה היא סון קובני, בולרו וגואחירה, הסגנונות של קובה של שנות הארבעים והחמישים, עם גיטרות, טרס (גיטרה קובנית קטנה), חצוצרה, פסנתר, כלי הקשה וקולות חמים וזקנים. השם לקוח ממועדון חברים ישן בהוואנה, שבו ניגנו פעם. Chan Chan, שפותח את האלבום, הוא שיר של קומפאי סגונדו, שהיה כמעט בן תשעים בזמן ההקלטה, ויש לו אחת המלודיות המוכרות של המוזיקה הלטינית. Dos Gardenias הוא בולרו רומנטי ועצוב, שאיברהים פרר, זמר שכבר כמעט פרש מהמוזיקה, שר בקול רך ונוגע. El Cuarto de Tula הוא ג׳אם שמח ומקפיץ, והפסנתרן רובן גונזלס מנגן לאורך כל האלבום בקלילות נפלאה.''',
'''האלבום זכה בגראמי, נמכר במיליוני עותקים, והפך לאחד מאלבומי מוזיקת העולם המצליחים בכל הזמנים. הבמאי וים ונדרס צילם סרט תיעודי על המוזיקאים, והם הופיעו בכל העולם, כולל בקרנגי הול בניו יורק. כמה מהם, שחיו שנים בעוני ובשכחה, הפכו לכוכבים בזקנתם.''',
'''זה אלבום לערב חם, עם חלון פתוח. התחילו ב־Chan Chan, ואחר כך שמעו את Dos Gardenias, וחשבו על הזמר שכמעט ויתר על השירה.''',
], [
('Chan Chan', 'אחת המלודיות המוכרות של המוזיקה הלטינית, בקול של קומפאי סגונדו.'),
('Dos Gardenias', 'בולרו רומנטי ועצוב, בקולו הרך והנוגע של איברהים פרר.'),
('El Cuarto de Tula', 'ג׳אם שמח ומקפיץ, שבו כל המוזיקאים שרים ומאלתרים יחד.'),
])

add(848, [
'''שנה אחרי Murder Ballads (אלבום 828), האלבום התיאטרלי והאפל על רציחות, הפתיע ניק קייב עם אלבום הפוך לגמרי. The Boatman's Call, שיצא בתחילת 1997, הוא אוסף של שירי אהבה שקטים ואישיים, שנכתבו אחרי פרידות כואבות ותקופה של חשבון נפש. אין כאן דמויות או סיפורים מומצאים: קייב מדבר בגוף ראשון, על אהבה, על אובדן, על אמונה ועל ספק, בכנות שלא נשמעה קודם במוזיקה שלו. רבים רואים בו את האלבום הטוב שלו.''',
'''המוזיקה פשוטה ומינימלית: בעיקר פסנתר והקול העמוק של קייב, עם בס שקט, אורגן, תופים עדינים ומדי פעם כינור. הבאד סידס מנגנים בעדינות, כמעט בלחישה, ומשאירים מקום למילים. Into My Arms, שיר הפתיחה, נפתח בשורה מפורסמת שבה קייב אומר שהוא לא מאמין באל שמתערב בעולם, ובכל זאת מתפלל לשלום של האישה שהוא אוהב. זה אחד משירי האהבה היפים שנכתבו, והוא שר אותו גם בהלוויה של חברו, הזמר מייקל האצ׳נס. (Are You) The One That I've Been Waiting For? הוא שיר מלא תקווה על המתנה לאהבה, ו־People Ain't No Good הוא שיר עצוב ויפה על אכזבה מאנשים, עם פסנתר ומיתרים.''',
'''The Boatman's Call הראה צד חדש לגמרי של ניק קייב, הצד הרך, הפגיע והמהורהר, שהלך והתחזק באלבומים שבאו אחריו. רבים שלא אהבו את המוזיקה הרועשת שלו מצאו כאן את הכניסה לעולם שלו.''',
'''שמעו את Into My Arms בשקט, עם המילים מול העיניים. ואחר כך עברו ל־Murder Ballads (אלבום 828), ושמעו כמה אמן אחד יכול להשתנות בשנה אחת.''',
], [
('Into My Arms', 'שיר אהבה ותפילה, עם פסנתר וקול עמוק, אחד היפים שנכתבו.'),
("(Are You) The One That I've Been Waiting For?", 'שיר מלא תקווה על המתנה לאהבה, עם פסנתר רך.'),
("People Ain't No Good", 'שיר עצוב ויפה על אכזבה מאנשים, עם פסנתר ומיתרים.'),
])

add(849, [
'''אחרי ההצלחה של Casanova (אלבום 818), שהפך את ניל הנון ואת דה דיוויין קומדי למוכרים בבריטניה, הוא רצה לעשות משהו קטן ושונה. A Short Album About Love, שיצא ב־1997, הוא באמת אלבום קצר, שבעה שירים בלבד, כולם על אהבה, והוא הוקלט עם תזמורת קטנה, באולם תיאטרון בלונדון. במקום הדמות המתוחכמת והאירונית של Casanova, כאן הנון נשמע רציני, רומנטי ופגיע, כמו זמר קרונר ישן ששר אהבה בלי בושה.''',
'''הצליל עשיר ותזמורתי: כלי מיתר, כלי נשיפה, פסנתר ותופים רכים, בסגנון של סקוט ווקר (אלבום 171) ושל זמרי הפופ הגדולים של שנות השישים. הקול של הנון עמוק וחם, והוא שר כאילו הוא על במה גדולה מול קהל אוהב. Everybody Knows (Except You) הוא שיר מצחיק ומתוק על אהבה שכולם רואים, חוץ מהאדם שאליו היא מכוונת, והוא הפך ללהיט במצעד הבריטי. Someone הוא בלדה ארוכה ויפה, ו־In Pursuit of Happiness, שיר הפתיחה, הוא שיר סוחף ודרמטי על החיפוש אחרי אושר. I'm All You Need סוגר את האלבום בשמחה תזמורתית גדולה.''',
'''A Short Album About Love הראה שהנון יכול להיות גם רציני ורומנטי, ולא רק מצחיק. האלבום, שנמשך פחות משלושים וחמש דקות, אהוב במיוחד על מעריציו, והוא אחת הדרכים הקלות להכיר את הכותב השנון הזה. הוא גם הוכיח שאפשר לשיר על אהבה בלי ציניות ובלי בדיחות, ועדיין להישמע חכם ומקורי.''',
'''השוו את האלבום ל־Casanova (אלבום 818), שיצא שנה קודם: אותו כותב, אבל עם הרבה פחות אירוניה. ושמעו את Everybody Knows (Except You), וחייכו.''',
], [
('Everybody Knows (Except You)', 'שיר מצחיק ומתוק על אהבה שכולם רואים, חוץ ממי שצריך.'),
('Someone', 'בלדה ארוכה ויפה, עם כלי מיתר וקול עמוק וחם.'),
('In Pursuit of Happiness', 'פתיחה סוחפת ודרמטית על החיפוש אחרי אושר.'),
])

add(850, [
'''קורנרשופ היא להקה שהקים טג׳ינדר סינג, בריטי ממוצא סיקי הודי, בתחילת שנות התשעים בלסטר שבאנגליה. השם שלה, "החנות בפינה", צוחק על הסטריאוטיפ הבריטי שלפיו כל המהגרים מהודו מחזיקים מכולות. בתחילת דרכה היא ניגנה פאנק רועש ופוליטי, אבל בהמשך הצליל התרחב, ו־When I Was Born for the 7th Time, שיצא ב־1997, מחבר בין עולמות רבים: רוק אינדי, היפ הופ, מוזיקה הודית, פולק, קאנטרי ומוזיקה אלקטרונית.''',
'''האלבום מלא בצלילים הודיים, כמו סיטאר, טבלה והרמוניום, יחד עם גיטרות, קצבים של היפ הופ, דגימות וקולות. סינג שר באנגלית ובפנג׳אבית, בקול רגוע ונינוח. Brimful of Asha הוא שיר שמח וקליל, שהוא מחווה לאשה בוסלה, זמרת מפורסמת מסרטי בוליווד, ולתקליטים הישנים שאהב. Sleep on the Left Side הוא שיר נינוח עם קצב מקפיץ ומלודיה נעימה. יש כאן גם דואט קאנטרי, Good to Be on the Road Back Home, ובסוף האלבום גרסה מפתיעה בפנג׳אבית לשיר Norwegian Wood של הביטלס, שבמקור הופיע בו דווקא סיטאר.''',
'''באותה שנה הוציא נורמן קוק, פטבוי סלים (אלבום 810), רמיקס מהיר ל־Brimful of Asha, והוא הגיע למקום הראשון במצעד הבריטי בתחילת 1998. אבל האלבום עצמו נחשב לאחד המקוריים של התקופה, דוגמה לאופן שבו מהגרים ובניהם שינו את המוזיקה הבריטית. Brimful of Asha הפך לאחד השירים האהובים של שנות התשעים בבריטניה, ושר אותו עד היום קהל מכל הגילים.''',
'''שמעו את Brimful of Asha, ואחר כך את הרמיקס של פטבוי סלים, והשוו. ואחר כך האזינו ל־Norwegian Wood, וחשבו על הביטלס בהודו.''',
], [
('Brimful of Asha', 'שיר שמח וקליל, מחווה לזמרת בוליווד אשה בוסלה ולתקליטים ישנים.'),
('Sleep on the Left Side', 'קצב מקפיץ ומלודיה נעימה, עם צלילים הודיים וגיטרות.'),
('Norwegian Wood (This Bird Has Flown)', 'שיר הביטלס בפנג׳אבית, עם סיטאר וקול רגוע.'),
])

add(851, [
'''דאפט פאנק הם שני צרפתים מפריז, תומא בנגלטר וגי־מנואל דה הומם־כריסטו, שנפגשו בבית הספר. בתחילת שנות התשעים הם ניגנו בלהקת רוק קטנה, ומבקר בריטי כתב עליה ביקורת קטלנית וכינה את המוזיקה שלה "פאנק טיפשי". הם לקחו את העלבון והפכו אותו לשם. אחר כך הם התאהבו במוזיקת האוס ובטכנו, ו־Homework, אלבום הבכורה שלהם, שהוקלט בחדר השינה של בנגלטר, יצא בתחילת 1997. הוא הפך להצלחה עולמית, והוביל גל של מוזיקה אלקטרונית צרפתית שנקרא "הטאץ׳ הצרפתי".''',
'''המוזיקה מחברת האוס של שיקגו, טכנו של דטרויט, פאנק ודיסקו, עם קצבים חזרתיים ומהפנטים, בס עבה, צלילים מעוותים של סינתיסייזרים ומעט מאוד מילים. הכל נשמע גס, מלוכלך ושמח, כמו מסיבה במחסן. Around the World, הלהיט הגדול, חוזר על שלוש המילים שבשמו שוב ושוב, מעל קו בס מקפיץ שאי אפשר לשכוח. Da Funk הוא קטע פאנקי ואיטי עם צליל של סינתיסייזר שמייבב, והקליפ שלו, על אדם עם ראש של כלב שמסתובב בניו יורק, הפך למפורסם. Revolution 909 מתחיל במסיבה שהמשטרה מפסיקה, וממשיך בקצב שלא נעצר. Teachers הוא מחווה לאמנים שלימדו אותם, ששמם מוקרא ברשימה ארוכה.''',
'''Homework הפך את דאפט פאנק לאחת הלהקות החשובות במוזיקה האלקטרונית. רק באלבום הבא הם התחילו להופיע בתחפושות של רובוטים, שהפכו לסימן ההיכר שלהם. גם השמות של הקטעים, כמו Revolution 909, הם מחווה לציוד המוזיקלי הישן שאהבו, מכונות תופים וסינתיסייזרים זולים מהשמונים.''',
'''שמעו את Teachers, ונסו לזהות כמה מהשמות ברשימה. והשוו את Homework ל־Dig Your Own Hole של הכימיקל בראדרס (אלבום 841), שיצא באותה שנה.''',
], [
('Around the World', 'שלוש מילים שחוזרות שוב ושוב, מעל קו בס מקפיץ ובלתי נשכח.'),
('Da Funk', 'קטע פאנקי ואיטי, עם סינתיסייזר מייבב וקצב כבד.'),
('Revolution 909', 'מתחיל במסיבה שהמשטרה מפסיקה, וממשיך בקצב שלא נעצר.'),
])
